---------------------------------------------------------------------
-- Helpers
---------------------------------------------------------------------

local FONT = Enum.Font.Arcade -- Press Start 2P: an 8px pixel font
local TEXT = 8
local WHITE = Color3.new(1, 1, 1)
local BLACK = Color3.new(0, 0, 0)
local CENTER = Vector2.new(0.5, 0.5)
local TWEEN_FAST = TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
local TWEEN_MED = TweenInfo.new(0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local TWEEN_POP = TweenInfo.new(0.25, Enum.EasingStyle.Back, Enum.EasingDirection.Out)

-- Classes whose default 1px border has to be switched off.
local GUI_CLASSES = {
	Frame = true,
	TextLabel = true,
	TextButton = true,
	TextBox = true,
	ScrollingFrame = true,
	ImageLabel = true,
}

local function tween(instance, info, props)
	local t = TweenService:Create(instance, info, props)
	t:Play()
	return t
end

-- Tweens when `animated`, otherwise sets the properties straight away.
local function apply(instance, animated, info, props)
	if animated then
		tween(instance, info, props)
	else
		for prop, value in pairs(props) do
			instance[prop] = value
		end
	end
end

local function connect(signal, fn)
	local conn = signal:Connect(fn)
	table.insert(Library._connections, conn)
	return conn
end

-- Sets theme-driven properties now and whenever the theme changes.
-- `map` is { PropertyName = "ThemeKey" }.
local function bind(instance, map)
	for prop, key in pairs(map) do
		instance[prop] = Library.Theme[key]
	end
	table.insert(Library._bindings, { instance, map })
	return instance
end

-- For state-dependent colours (e.g. a toggle that is accent only when on).
local function onTheme(fn)
	table.insert(Library._themeCallbacks, fn)
	fn(Library.Theme)
end

local function create(class, props, children)
	local instance = Instance.new(class)
	if GUI_CLASSES[class] then
		instance.BorderSizePixel = 0
	end
	local parent, theme
	for key, value in pairs(props or {}) do
		if key == "Parent" then
			parent = value
		elseif key == "Theme" then
			theme = value
		else
			instance[key] = value
		end
	end
	if theme then
		bind(instance, theme)
	end
	for _, child in ipairs(children or {}) do
		child.Parent = instance
	end
	if parent then
		instance.Parent = parent
	end
	return instance
end

-- True when `class` can be created and every property in `writes` accepts
-- the given value. New classes (UIShadow, UIBlur) can exist on a client
-- before all of their properties do.
local function canUse(class, writes)
	local ok, instance = pcall(Instance.new, class)
	if not ok or not instance then
		return false
	end
	local works = pcall(function()
		for property, value in pairs(writes) do
			instance[property] = value
		end
	end)
	pcall(function()
		instance:Destroy()
	end)
	return works
end

Library.Support.UIShadow = canUse("UIShadow", {
	Enabled = true,
	Color = Color3.new(1, 1, 1),
	Transparency = 0.5,
	BlurRadius = UDim.new(0, 8),
	Spread = UDim2.fromOffset(1, 1),
})
Library.Support.UIBlur = canUse("UIBlur", { Enabled = true })

-- Logs a cosmetic failure once instead of letting it stop the window.
local reported = {}
local function soft(what, fn, ...)
	local ok, err = pcall(fn, ...)
	if not ok and not reported[what] then
		reported[what] = true
		warn("[Sakura UI] " .. what .. " failed, continuing without it: " .. tostring(err))
	end
	return ok
end

-- A sharp 1px border. `key` is a theme key, or nil for a stroke whose colour
-- the caller manages.
local function stroke(key)
	local instance = create("UIStroke", {
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Thickness = 1,
	})
	pcall(function()
		instance.LineJoinMode = Enum.LineJoinMode.Miter
	end)
	if key ~= false then
		bind(instance, { Color = key or "Stroke" })
	end
	return instance
end

local function padding(top, right, bottom, left)
	right = right or top
	return create("UIPadding", {
		PaddingTop = UDim.new(0, top),
		PaddingRight = UDim.new(0, right),
		PaddingBottom = UDim.new(0, bottom or top),
		PaddingLeft = UDim.new(0, left or right),
	})
end

local function label(props)
	props.BackgroundTransparency = 1
	props.Font = props.Font or FONT
	props.TextSize = props.TextSize or TEXT
	props.TextXAlignment = props.TextXAlignment or Enum.TextXAlignment.Left
	props.Theme = props.Theme or { TextColor3 = "Text" }
	return create("TextLabel", props)
end

-- Invisible button covering its parent; the usual click target.
local function clickArea(parent)
	return create("TextButton", {
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Text = "",
		AutoButtonColor = false,
		ZIndex = 5,
		Parent = parent,
	})
end

local function safeCall(fn, ...)
	if type(fn) ~= "function" then
		return
	end
	task.spawn(function(...)
		local ok, err = pcall(fn, ...)
		if not ok then
			warn("[Sakura UI] callback error: " .. tostring(err))
		end
	end, ...)
end

local function isPress(input)
	return input.UserInputType == Enum.UserInputType.MouseButton1
		or input.UserInputType == Enum.UserInputType.Touch
end

-- Follows a press until it is released. `onMove` receives the pointer position.
local function trackDrag(startInput, onMove, onEnd)
	local moveConn, endConn
	moveConn = UserInputService.InputChanged:Connect(function(input)
		if input == startInput or input.UserInputType == Enum.UserInputType.MouseMovement then
			onMove(input.Position)
		end
	end)
	endConn = startInput.Changed:Connect(function()
		if startInput.UserInputState == Enum.UserInputState.End then
			moveConn:Disconnect()
			endConn:Disconnect()
			if onEnd then
				onEnd()
			end
		end
	end)
end

local function round(value, step)
	local result = math.floor(value / step + 0.5) * step
	-- trim float noise such as 0.30000000000000004
	return tonumber(string.format("%.6f", result))
end

local function colorToHex(color)
	return string.format(
		"%02X%02X%02X",
		math.floor(color.R * 255 + 0.5),
		math.floor(color.G * 255 + 0.5),
		math.floor(color.B * 255 + 0.5)
	)
end

local function hexToColor(hex)
	hex = string.gsub(tostring(hex), "#", "")
	local r, g, b = string.match(hex, "^(%x%x)(%x%x)(%x%x)$")
	if not r then
		return nil
	end
	return Color3.fromRGB(tonumber(r, 16), tonumber(g, 16), tonumber(b, 16))
end

local function mountGui(gui)
	if type(gethui) == "function" then
		local ok = pcall(function()
			gui.Parent = gethui()
		end)
		if ok then
			return
		end
	end
	if type(syn) == "table" and type(syn.protect_gui) == "function" then
		pcall(syn.protect_gui, gui)
	elseif type(protectgui) == "function" then
		pcall(protectgui, gui)
	end
	local ok = pcall(function()
		gui.Parent = CoreGui
	end)
	if not ok then
		-- No CoreGui access (e.g. running in Studio): fall back to PlayerGui.
		gui.Parent = Players.LocalPlayer:WaitForChild("PlayerGui")
	end
end

-- Three stacked ScreenGuis. The backdrop is thousands of static frames, so it
-- lives in its own gui and is not re-laid-out when the controls animate; the
-- glow sits below it so only the part outside the window shows.
local function getGuis()
	local guis = Library._guis
	if guis.main then
		return guis
	end
	for index, key in ipairs({ "glow", "back", "main" }) do
		local gui = create("ScreenGui", {
			Name = HttpService:GenerateGUID(false),
			ResetOnSpawn = false,
			IgnoreGuiInset = true,
			ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
			DisplayOrder = 9000 + index,
		})
		mountGui(gui)
		guis[key] = gui
	end
	return guis
end

