local BLOOM_ROSE = {
	P = SPRITE_COLORS.R,
	L = rgb(255, 128, 160),
	D = SPRITE_COLORS.r,
	Y = SPRITE_COLORS.Y,
	O = SPRITE_COLORS.O,
}

-- Builds a sprite out of frames: one per horizontal run of equal pixels,
-- stretched downwards while the rows below repeat the same run. Also returns
-- the frames grouped by sprite character, for recolouring.
local function sprite(rows, scale, colors)
	colors = colors or SPRITE_COLORS
	scale = scale or 1
	local height = #rows
	local width = #rows[1]
	local holder = create("Frame", {
		Size = UDim2.fromOffset(width * scale, height * scale),
		BackgroundTransparency = 1,
	})
	local parts = {}
	local open = {} -- ["x:w:char"] = frame still growing downwards
	for y = 1, height do
		local row = rows[y]
		local seen = {}
		local x = 1
		while x <= width do
			local char = string.sub(row, x, x)
			local run = 1
			while x + run <= width and string.sub(row, x + run, x + run) == char do
				run = run + 1
			end
			local color = colors[char]
			if color then
				local key = x .. ":" .. run .. ":" .. char
				local entry = open[key]
				if entry and entry.last == y - 1 then
					entry.rows = entry.rows + 1
					entry.last = y
					entry.frame.Size = UDim2.fromOffset(run * scale, entry.rows * scale)
				else
					entry = {
						rows = 1,
						last = y,
						frame = create("Frame", {
							Position = UDim2.fromOffset((x - 1) * scale, (y - 1) * scale),
							Size = UDim2.fromOffset(run * scale, scale),
							BackgroundColor3 = color,
							Parent = holder,
						}),
					}
					open[key] = entry
					parts[char] = parts[char] or {}
					table.insert(parts[char], entry.frame)
				end
				seen[key] = true
			end
			x = x + run
		end
		for key in pairs(open) do
			if not seen[key] then
				open[key] = nil
			end
		end
	end
	return holder, parts
end

---------------------------------------------------------------------
-- Glow (UIShadow)
---------------------------------------------------------------------

local glows = {}

-- "window" and "image" glows use SurfaceColor; controls use ControlColor.
local function glowColor(kind)
	local settings = Library.Glow
	local specific
	if kind == "logo" then
		specific = settings.LogoColor or settings.SurfaceColor
	elseif kind == "window" or kind == "image" then
		specific = settings.SurfaceColor
	else
		specific = settings.ControlColor
	end
	return specific or settings.Color or Library.Theme.Glow or Library.Theme.Accent
end

local function writeGlow(entry, pulse)
	local settings = Library.Glow
	if entry.kind == "logo" then
		-- A logo's glow is a white image tinted at runtime; it ignores Enabled.
		local color = glowColor("logo")
		local strength = math.clamp(settings.LogoStrength or 0.85, 0, 1) * (pulse or 1)
		entry.glow.ImageColor3 = color
		entry.glow.ImageTransparency = 1 - strength
		entry.bloom.ImageColor3 = color
		entry.bloom.ImageTransparency = 1 - strength * 0.4
		return
	end
	local strength = math.clamp(settings.Strength, 0, 1)
	local size = math.max(0, settings.Size)
	local shadow = entry.shadow
	if entry.kind == "image" then
		-- Fallback for clients without UIShadow: a nine-sliced soft image.
		local reach = math.floor(size * 1.4) + settings.Spread
		shadow.Visible = settings.Enabled
		shadow.Size = UDim2.new(1, reach * 2, 1, reach * 2)
		shadow.ImageColor3 = glowColor("image")
		shadow.ImageTransparency = 1 - strength * (pulse or 1)
		return
	end
	if entry.kind == "window" then
		shadow.Enabled = settings.Enabled
		shadow.BlurRadius = UDim.new(0, size)
		shadow.Spread = UDim2.fromOffset(settings.Spread, settings.Spread)
		shadow.Transparency = 1 - strength * (pulse or 1)
	elseif entry.kind == "text" then
		shadow.Enabled = settings.Enabled and settings.Elements
		shadow.BlurRadius = UDim.new(0, math.max(2, math.floor(size * 0.2)))
		shadow.Transparency = 1 - math.clamp(settings.ElementStrength, 0, 1) * 0.9
	else
		shadow.Enabled = settings.Enabled and settings.Elements and entry.on
		shadow.BlurRadius = UDim.new(0, math.max(2, math.floor(size * 0.25)))
		shadow.Transparency = 1 - math.clamp(settings.ElementStrength, 0, 1)
	end
	shadow.Color = glowColor(entry.kind)
end

local function applyGlow(entry, pulse)
	soft("glow", writeGlow, entry, pulse)
end

-- kind: "window" (the big outer glow), "element" (small glow on a control,
-- shown while `on`), or "text" (glow that follows the glyphs).
local function addGlow(parent, kind)
	local entry
	if Library.Support.UIShadow then
		local made, shadow = pcall(Instance.new, "UIShadow")
		if not made then
			return nil
		end
		if kind == "text" then
			local ok = pcall(function()
				shadow.Mode = Enum.ApplyShadowMode.Text
			end)
			if not ok then
				-- Without text mode this would be a box around the label.
				shadow:Destroy()
				return nil
			end
		end
		shadow.Parent = parent
		entry = { shadow = shadow, kind = kind, on = false }
	elseif kind == "window" then
		entry = {
			kind = "image",
			shadow = create("ImageLabel", {
				AnchorPoint = CENTER,
				Position = UDim2.fromScale(0.5, 0.5),
				BackgroundTransparency = 1,
				Image = "rbxassetid://6014261993",
				ScaleType = Enum.ScaleType.Slice,
				SliceCenter = Rect.new(49, 49, 450, 450),
				ZIndex = 0,
				Parent = parent,
			}),
		}
	else
		return nil
	end
	table.insert(glows, entry)
	applyGlow(entry)
	return entry
end

local function setGlowOn(entry, on)
	if entry then
		entry.on = on
		applyGlow(entry)
	end
end

-- Library:SetGlow({ Enabled, Size, Spread, Strength, ElementStrength, Pulse, Elements,
--                   Color, SurfaceColor, ControlColor })
-- Size and Spread are pixels, strengths are 0..1. A colour set to false follows the
-- accent again. SurfaceColor tints the window glow, ControlColor the small glows.
function Library:SetGlow(settings)
	for key, value in pairs(settings or {}) do
		if (key == "Color" or key == "SurfaceColor" or key == "ControlColor" or key == "LogoColor") and value == false then
			self.Glow[key] = nil
		else
			self.Glow[key] = value
		end
	end
	for _, entry in ipairs(glows) do
		applyGlow(entry)
	end
end

---------------------------------------------------------------------
-- Glass (UIBlur)
---------------------------------------------------------------------

local glasses = {}
local frost = { Enabled = true } -- see Library:SetFrost

local function applyGlass(entry)
	local settings = Library.Glass
	local transparency = math.clamp(settings.Transparency, 0, 0.95)
	if entry.kind == "header" then
		transparency = transparency * 0.55
	end
	entry.frame.BackgroundTransparency = transparency
	local blur = entry.blur
	if blur then
		local on = settings.Blur ~= "Off" and not frost.Images
		soft("blur", function()
			blur.Enabled = on
		end)
		if on then
			pcall(function()
				blur.Strength = Enum.UIBlurStrength[settings.Blur]
			end)
		end
	end
end

-- Makes `frame` a frosted panel: a tinted, see-through background with a
-- UIBlur behind it where the client supports one.
local function glass(frame, kind)
	local entry = { frame = frame, kind = kind or "panel", notIn = {} }
	pcall(frame.SetAttribute, frame, "SakuraGlass", entry.kind)
	if Library.Support.UIBlur then
		soft("blur", function()
			local blur = Instance.new("UIBlur")
			blur.Parent = frame
			entry.blur = blur
		end)
	end
	table.insert(glasses, entry)
	applyGlass(entry)
	return entry
end

---------------------------------------------------------------------
-- Frost: baked blur. UIBlur does not blur what is behind a panel on most
-- clients, so Library:SetFrost takes pre-blurred images of each backdrop
-- scene, and every frame each glass panel gets the matching crop drawn
-- right under it. The panel's own tint then sits on top as usual.
--
-- Library:SetFrost({
--     Width = 1006, Height = 586,          -- content size the images were baked at
--     ImageWidth = 252, ImageHeight = 147, -- pixel size of the images
--     Images = { Dusk = { Light = "rbxasset...", Medium = ..., Heavy = ... }, ... },
--     Enabled = true,
-- })
-- Frost is used only when the window's content size matches Width x Height,
-- the backdrop is shown and Glass.Blur is not "Off"; otherwise the tint is used.
---------------------------------------------------------------------

Library.Frost = frost

function Library:SetFrost(settings)
	for key, value in pairs(settings or {}) do
		frost[key] = value
	end
	for _, entry in ipairs(glasses) do
		applyGlass(entry)
	end
end

local function frostImage(window)
	if not (frost.Enabled and frost.Images and window._frostSize and window._frostLayer) then
		return nil
	end
	if not window._scene.Instance.Visible then
		return nil
	end
	local level = Library.Glass.Blur
	if level == "Off" then
		return nil
	end
	local scene = Library.Theme.Scene
	local set = type(scene) == "string" and frost.Images[scene]
	local image = set and set[level]
	if not image then
		return nil
	end
	return image
end

-- Crop of the frost image under a panel: rect (absolute) -> content pixels.
-- Returns position, size (content pixels) and rect offset, size (image pixels),
-- or nil when nothing of the panel is visible.
-- W, H: the window's content size (the image is stretched over it when a resized
-- window no longer matches the size it was baked at).
function Library._frostCrop(contentPos, scale, x0, y0, x1, y1, W, H)
	if scale <= 0 then
		return nil
	end
	W, H = W or frost.Width, H or frost.Height
	local lx0 = math.max(0, (x0 - contentPos.X) / scale)
	local ly0 = math.max(0, (y0 - contentPos.Y) / scale)
	local lx1 = math.min(W, (x1 - contentPos.X) / scale)
	local ly1 = math.min(H, (y1 - contentPos.Y) / scale)
	if lx1 - lx0 < 1 or ly1 - ly0 < 1 then
		return nil
	end
	local kx, ky = frost.ImageWidth / W, frost.ImageHeight / H
	return Vector2.new(lx0, ly0), Vector2.new(lx1 - lx0, ly1 - ly0),
		Vector2.new(lx0 * kx, ly0 * ky), Vector2.new((lx1 - lx0) * kx, (ly1 - ly0) * ky)
end

local function updateFrost(window)
	local image = frostImage(window)
	local layer = window._frostLayer
	if not layer then
		return
	end
	layer.Visible = image ~= nil
	if not image then
		return
	end
	local content = window._content
	local scale = window._scales[1] and window._scales[1].Scale or 1
	local cp = content.AbsolutePosition
	for i = #glasses, 1, -1 do
		local entry = glasses[i]
		local frame = entry.frame
		if not frame.Parent then
			if entry.copy then
				entry.copy:Destroy()
			end
			table.remove(glasses, i)
		elseif not entry.notIn[window] then
			if entry.window ~= window then
				if frame:IsDescendantOf(content) then
					entry.window = window
				else
					entry.notIn[window] = true
				end
			end
			if entry.window == window then
				local pos, size = frame.AbsolutePosition, frame.AbsoluteSize
				local x0, y0, x1, y1 = pos.X, pos.Y, pos.X + size.X, pos.Y + size.Y
				local shown = true
				local node = frame
				while node and node ~= content do
					if node:IsA("GuiObject") then
						if not node.Visible then
							shown = false
							break
						end
						if node ~= frame and node.ClipsDescendants then
							local p, s = node.AbsolutePosition, node.AbsoluteSize
							x0, y0 = math.max(x0, p.X), math.max(y0, p.Y)
							x1, y1 = math.min(x1, p.X + s.X), math.min(y1, p.Y + s.Y)
						end
					end
					node = node.Parent
				end
				local at, extent, offset, rect
				if shown then
					at, extent, offset, rect = Library._frostCrop(cp, scale, x0, y0, x1, y1, window._frostSize.X, window._frostSize.Y)
				end
				if not entry.copy then
					entry.copy = create("ImageLabel", {
						Name = "Frost",
						BackgroundTransparency = 1,
						Parent = layer,
					})
				end
				local copy = entry.copy
				copy.Visible = at ~= nil
				if at then
					if copy.Image ~= image then
						copy.Image = image
					end
					copy.Position = UDim2.fromOffset(at.X, at.Y)
					copy.Size = UDim2.fromOffset(extent.X, extent.Y)
					copy.ImageRectOffset = offset
					copy.ImageRectSize = rect
				end
			end
		end
	end
end

---------------------------------------------------------------------
-- Logo: an image title whose glow is a separate white layer, tinted at
-- runtime, so the glow colour can change.
--
-- Library:SetLogo({ Image = "rbxasset...", Glow = "rbxasset...", Width = 448, Height = 110 })
-- Image is the white logo, Glow the white glow; Width/Height give the aspect.
-- The glow follows Glow.LogoColor (then SurfaceColor, Color, accent) and
-- Glow.LogoStrength (0..1).
---------------------------------------------------------------------

function Library:SetLogo(asset)
	self._logo = asset
end

-- A Frame holding the logo `height` pixels tall, or nil without SetLogo.
function Library:CreateLogo(height, parent)
	local asset = self._logo
	if not (asset and asset.Image) then
		return nil
	end
	height = height or 24
	local width = math.floor(height * (asset.Width or 4) / (asset.Height or 1) + 0.5)
	local holder = create("Frame", {
		Name = "Logo",
		Size = UDim2.fromOffset(width, height),
		BackgroundTransparency = 1,
		Parent = parent,
	})
	local glowImage = asset.Glow or asset.Image
	local bloom = create("ImageLabel", {
		Name = "Bloom",
		AnchorPoint = CENTER,
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromScale(1.06, 1.3),
		BackgroundTransparency = 1,
		Image = glowImage,
		ZIndex = 1,
		Parent = holder,
	})
	local glowLabel = create("ImageLabel", {
		Name = "Glow",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Image = glowImage,
		ZIndex = 2,
		Parent = holder,
	})
	create("ImageLabel", {
		Name = "Text",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Image = asset.Image,
		ZIndex = 3,
		Parent = holder,
	})
	local entry = { kind = "logo", glow = glowLabel, bloom = bloom, holder = holder }
	table.insert(glows, entry)
	applyGlow(entry)
	return holder, entry
end

-- Library:SetGlass({ Blur = "Off" | "Light" | "Medium" | "Heavy", Transparency = 0..0.95 })
function Library:SetGlass(settings)
	for key, value in pairs(settings or {}) do
		self.Glass[key] = value
	end
	for _, entry in ipairs(glasses) do
		applyGlass(entry)
	end
end

---------------------------------------------------------------------
-- Backdrop scene
---------------------------------------------------------------------

local ALPHABET = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"
local DIGIT = {}
for i = 1, #ALPHABET do
	DIGIT[string.byte(ALPHABET, i)] = i - 1
end

local SKY_BANDS = 18
local ANCHOR_X = { l = 0, c = 0.5, r = 1 }

-- "RRGGBB" or "RRGGBBAA" -> Color3, transparency
local function hexColor(hex)
	local r = tonumber(string.sub(hex, 1, 2), 16)
	local g = tonumber(string.sub(hex, 3, 4), 16)
	local b = tonumber(string.sub(hex, 5, 6), 16)
	local alpha = 255
	if #hex >= 8 then
		alpha = tonumber(string.sub(hex, 7, 8), 16)
	end
	return Color3.fromRGB(r, g, b), 1 - alpha / 255
end

local function scenePalette(theme)
	local palette = theme.Scene
	if type(palette) == "string" then
		palette = SCENE_PALETTES[palette]
	end
	return palette or SCENE_PALETTES.Dusk
end

-- Sky colour for band `index`, blended across the palette's key colours.
local function skyColor(palette, index)
	local keys = palette.sky
	local t = (index - 1) / (SKY_BANDS - 1) * (#keys - 1)
	local k = math.min(#keys - 1, math.floor(t) + 1)
	local a = hexColor(keys[k])
	local b = hexColor(keys[k + 1])
	return a:Lerp(b, t - (k - 1))
end

-- Draws the backdrop into `parent`. Every rectangle in the generated data is
-- one Frame; `pixel` is the on-screen size of one art pixel.
local function buildScene(parent, pixel)
	local palette = scenePalette(Library.Theme)
	local scene = { _bands = {}, _strips = {}, _slots = {} }
	local holder = create("Frame", {
		Name = "Scene",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
	})
	scene.Instance = holder

	for i = 1, SKY_BANDS do
		scene._bands[i] = create("Frame", {
			Position = UDim2.fromScale(0, (i - 1) / SKY_BANDS),
			Size = UDim2.new(1, 0, 1 / SKY_BANDS, 1),
			BackgroundColor3 = skyColor(palette, i),
			Parent = holder,
		})
	end
	for i, strip in ipairs(SCENE_STRIPS) do
		scene._strips[i] = create("Frame", {
			Position = UDim2.new(0, 0, 1, -strip[1] * pixel),
			Size = UDim2.new(1, 0, 0, strip[2] * pixel),
			BackgroundColor3 = hexColor(palette[strip[3]]),
			Parent = holder,
		})
	end

	local colors, alphas = {}, {}
	for slot, name in ipairs(SCENE_SLOTS) do
		colors[slot], alphas[slot] = hexColor(palette[name])
		scene._slots[slot] = {}
	end
	for _, group in ipairs(SCENE_GROUPS) do
		local anchor, data = group[1], group[4]
		local ax = ANCHOR_X[string.sub(anchor, 2, 2)]
		local ay = string.sub(anchor, 1, 1) == "t" and 0 or 1
		local container = create("Frame", {
			AnchorPoint = Vector2.new(ax, ay),
			Position = UDim2.fromScale(ax, ay),
			Size = UDim2.fromOffset(group[2] * pixel, group[3] * pixel),
			BackgroundTransparency = 1,
			Parent = holder,
		})
		if type(data) == "table" then
			data = table.concat(data)
		end
		-- 7 characters per rectangle: x (2), y (2), width, height, palette slot.
		for i = 1, #data, 7 do
			local a, b, c, d, e, f, g = string.byte(data, i, i + 6)
			local slot = DIGIT[g] + 1
			local frame = Instance.new("Frame")
			frame.BorderSizePixel = 0
			frame.Position = UDim2.fromOffset((DIGIT[a] * 62 + DIGIT[b]) * pixel, (DIGIT[c] * 62 + DIGIT[d]) * pixel)
			frame.Size = UDim2.fromOffset(DIGIT[e] * pixel, DIGIT[f] * pixel)
			frame.BackgroundColor3 = colors[slot]
			frame.BackgroundTransparency = alphas[slot]
			frame.Parent = container
			local list = scene._slots[slot]
			list[#list + 1] = frame
		end
	end

	function scene:Recolor(newPalette)
		for i, band in ipairs(self._bands) do
			band.BackgroundColor3 = skyColor(newPalette, i)
		end
		for i, strip in ipairs(SCENE_STRIPS) do
			self._strips[i].BackgroundColor3 = hexColor(newPalette[strip[3]])
		end
		for slot, name in ipairs(SCENE_SLOTS) do
			local color, alpha = hexColor(newPalette[name])
			for _, frame in ipairs(self._slots[slot]) do
				frame.BackgroundColor3 = color
				frame.BackgroundTransparency = alpha
			end
		end
	end

	holder.Parent = parent
	return scene
end

-- Petals drifting across `layer`, snapped to the art-pixel grid.
local function startPetals(window, layer, width, height, pixel)
	local petals = { _items = {} }
	function petals:SetBounds(w, h)
		width, height = w, h
	end
	local shapes = { { 2, 1 }, { 1, 1 }, { 2, 2 }, { 1, 2 } }
	local slots = { "roseLight", "roseHi", "whiteLight", "whiteHi", "roseMid" }
	local clock = 0

	local function place(item, anywhere)
		item.x = math.random() * (width + 80) - 80
		item.y = anywhere and math.random() * height or -pixel * 2
		item.fall = 16 + math.random() * 22
		item.drift = 8 + math.random() * 16
		item.sway = 6 + math.random() * 10
		item.phase = math.random() * 6.28
	end

	function petals:Refresh()
		local settings = Library.Petals
		local palette = scenePalette(Library.Theme)
		local wanted = settings.Enabled and math.clamp(math.floor(settings.Count), 0, 60) or 0
		while #self._items > wanted do
			table.remove(self._items).frame:Destroy()
		end
		while #self._items < wanted do
			local shape = shapes[math.random(1, #shapes)]
			local item = {
				frame = create("Frame", {
					Size = UDim2.fromOffset(shape[1] * pixel, shape[2] * pixel),
					Parent = layer,
				}),
				slot = slots[math.random(1, #slots)],
			}
			place(item, true)
			table.insert(self._items, item)
		end
		for _, item in ipairs(self._items) do
			item.frame.BackgroundColor3 = hexColor(palette[item.slot])
		end
	end

	connect(RunService.Heartbeat, function(dt)
		if not window.Visible or window.Minimized then
			return
		end
		local speed = Library.Petals.Speed
		clock = clock + dt
		for _, item in ipairs(petals._items) do
			item.y = item.y + item.fall * speed * dt
			item.x = item.x + (item.drift + math.sin(clock * 1.7 + item.phase) * item.sway) * speed * dt
			if item.y > height or item.x > width then
				place(item, false)
			end
			local x = math.floor(item.x / pixel) * pixel
			local y = math.floor(item.y / pixel) * pixel
			if x ~= item.px or y ~= item.py then
				item.px, item.py = x, y
				item.frame.Position = UDim2.fromOffset(x, y)
			end
		end
	end)

	petals:Refresh()
	return petals
end

-- Library:SetPetals({ Enabled, Count, Speed })
function Library:SetPetals(settings)
	for key, value in pairs(settings or {}) do
		self.Petals[key] = value
	end
	for _, window in ipairs(self._windows) do
		window._petals:Refresh()
	end
end

---------------------------------------------------------------------
-- Theme switching
---------------------------------------------------------------------

local function applyTheme()
	local theme = Library.Theme
	for _, binding in ipairs(Library._bindings) do
		local instance, map = binding[1], binding[2]
		for prop, key in pairs(map) do
			instance[prop] = theme[key]
		end
	end
	for _, fn in ipairs(Library._themeCallbacks) do
		fn(theme)
	end
	for _, entry in ipairs(glows) do
		applyGlow(entry)
	end
end

-- Accepts a theme name or a table. Missing keys fall back to Dusk.
function Library:SetTheme(theme)
	local name
	if type(theme) == "string" then
		name = theme
		theme = self.Themes[theme]
	end
	if type(theme) ~= "table" then
		return
	end
	local resolved = {}
	for key, value in pairs(self.Themes.Dusk) do
		resolved[key] = value
	end
	for key, value in pairs(theme) do
		resolved[key] = value
	end
	if self._accent then
		resolved.Accent = self._accent
	end
	self._themeSource = theme
	self.ThemeName = name or self.ThemeName
	self.Theme = resolved
	applyTheme()
	local palette = scenePalette(resolved)
	for _, window in ipairs(self._windows) do
		window._scene:Recolor(palette)
		window._petals:Refresh()
	end
end

-- Overrides the theme's accent colour. Pass nil to go back to the theme's own.
function Library:SetAccent(color)
	self._accent = color
	self:SetTheme(self._themeSource or self.Themes[self.ThemeName] or self.Themes.Dusk)
end

---------------------------------------------------------------------
-- Notifications and watermark
---------------------------------------------------------------------

local notifyHolder
local watermark
local toasts = {}

local function placeNotifications()
	if not notifyHolder then
		return
	end
	local settings = Library.Notifications
	local right = settings.Side ~= "Left"
	local bottom = settings.Anchor ~= "Top"
	notifyHolder.AnchorPoint = Vector2.new(right and 1 or 0, bottom and 1 or 0)
	notifyHolder.Position = UDim2.new(right and 1 or 0, right and -18 or 18, bottom and 1 or 0, bottom and -18 or 52)
	local layout = notifyHolder:FindFirstChildOfClass("UIListLayout")
	if layout then
		layout.VerticalAlignment = bottom and Enum.VerticalAlignment.Bottom or Enum.VerticalAlignment.Top
	end
end

-- Library:SetNotifications({ Side = "Left" | "Right", Anchor = "Top" | "Bottom", Max = 5 })
function Library:SetNotifications(settings)
	for key, value in pairs(settings or {}) do
		self.Notifications[key] = value
	end
	placeNotifications()
end

-- The ScreenGui that holds the window controls. Parent your own overlays here.
function Library:GetScreenGui()
	return getGuis().main
end

-- While `active`, the toggle key and keybinds ignore input (for capturing a key yourself).
function Library:CaptureKeys(active)
	self._listening = active == true
end

function Library:Notify(config)
	if type(config) == "string" then
		config = { Content = config }
	end
	local duration = config.Duration or 4
	local theme = self.Theme

	if not notifyHolder then
		notifyHolder = create("Frame", {
			Name = "Notifications",
			Size = UDim2.new(0, 300, 1, -70),
			BackgroundTransparency = 1,
			Parent = getGuis().main,
		}, {
			create("UIListLayout", {
				SortOrder = Enum.SortOrder.LayoutOrder,
				Padding = UDim.new(0, 10),
			}),
		})
		placeNotifications()
	end
	local offscreen = self.Notifications.Side == "Left" and UDim2.new(0, -320, 0, 0) or UDim2.new(1, 320, 0, 0)

	local wrapper = create("Frame", {
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Parent = notifyHolder,
	})
	table.insert(toasts, wrapper)
	while #toasts > math.max(1, self.Notifications.Max) do
		local oldest = table.remove(toasts, 1)
		if oldest.Parent then
			oldest:Destroy()
		end
	end

	local progress = create("Frame", {
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.new(0, 0, 1, 0),
		Size = UDim2.new(1, 0, 0, 2),
		BackgroundColor3 = theme.Accent,
	})
	local icon = sprite(SPRITES.bloom, 1)
	icon.Position = UDim2.fromOffset(10, 10)

	-- Colours are read once: a toast is gone before a theme change matters.
	local card = create("Frame", {
		Position = offscreen,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundColor3 = theme.Header,
		BackgroundTransparency = math.clamp(self.Glass.Transparency * 0.55, 0, 0.95),
		Parent = wrapper,
	}, {
		create("UIStroke", {
			ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
			Thickness = 1,
			Color = theme.Accent,
		}),
		icon,
		progress,
		create("Frame", {
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
		}, {
			padding(10, 12, 14, 26),
			create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 6) }),
			create("TextLabel", {
				LayoutOrder = 1,
				Size = UDim2.new(1, 0, 0, 8),
				BackgroundTransparency = 1,
				Font = FONT,
				TextSize = TEXT,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextColor3 = theme.Accent,
				Text = config.Title or "notification",
			}),
			create("TextLabel", {
				LayoutOrder = 2,
				Size = UDim2.new(1, 0, 0, 0),
				AutomaticSize = Enum.AutomaticSize.Y,
				BackgroundTransparency = 1,
				Font = FONT,
				TextSize = TEXT,
				LineHeight = 1.4,
				TextWrapped = true,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextYAlignment = Enum.TextYAlignment.Top,
				TextColor3 = theme.Text,
				Text = config.Content or "",
			}),
		}),
	})
	if self.Support.UIBlur then
		soft("blur", function()
			local blur = Instance.new("UIBlur")
			pcall(function()
				blur.Strength = Enum.UIBlurStrength[self.Glass.Blur]
			end)
			blur.Enabled = self.Glass.Blur ~= "Off"
			blur.Parent = card
		end)
	end
	if self.Support.UIShadow and self.Glow.Enabled then
		soft("glow", function()
			local shadow = Instance.new("UIShadow")
			shadow.Color = glowColor("window")
			shadow.BlurRadius = UDim.new(0, math.max(4, math.floor(self.Glow.Size * 0.5)))
			shadow.Transparency = 1 - math.clamp(self.Glow.Strength, 0, 1) * 0.8
			shadow.Parent = card
		end)
	end

	tween(card, TWEEN_MED, { Position = UDim2.new(0, 0, 0, 0) })
	tween(progress, TweenInfo.new(duration, Enum.EasingStyle.Linear), { Size = UDim2.new(0, 0, 0, 2) })

	task.delay(duration, function()
		if not wrapper.Parent then
			return
		end
		local out = tween(card, TWEEN_MED, { Position = offscreen })
		out.Completed:Connect(function()
			local at = table.find(toasts, wrapper)
			if at then
				table.remove(toasts, at)
			end
			wrapper:Destroy()
		end)
	end)
end

-- A small always-on bar in the top left corner. Pass false to hide it.
function Library:SetWatermark(text)
	if not watermark then
		if not text then
			return
		end
		local icon = sprite(SPRITES.bloom, 1)
		icon.AnchorPoint = Vector2.new(0, 0.5)
		icon.Position = UDim2.new(0, -15, 0.5, 0)
		local frame = create("Frame", {
			Name = "Watermark",
			Position = UDim2.fromOffset(16, 16),
			Size = UDim2.fromOffset(0, 22),
			AutomaticSize = Enum.AutomaticSize.X,
			Theme = { BackgroundColor3 = "Header" },
			Parent = getGuis().main,
		}, {
			stroke("Accent"),
			padding(0, 10, 0, 25),
			icon,
		})
		glass(frame, "header")
		setGlowOn(addGlow(frame, "element"), true)
		watermark = {
			frame = frame,
			label = label({
				Size = UDim2.new(0, 0, 1, 0),
				AutomaticSize = Enum.AutomaticSize.X,
				Parent = frame,
			}),
		}
	end
	watermark.frame.Visible = text ~= false and text ~= nil
	if text then
		watermark.label.Text = tostring(text)
	end
end

---------------------------------------------------------------------
-- Elements (shared by every groupbox)
---------------------------------------------------------------------

local Elements = {}
Elements.__index = Elements

local function nextOrder(self)
	self._order = (self._order or 0) + 1
	return self._order
end

local function makeRow(self, height)
	return create("Frame", {
		LayoutOrder = nextOrder(self),
		Size = UDim2.new(1, 0, 0, height),
		BackgroundTransparency = 1,
		Parent = self.Container,
	})
end

-- A bordered inset box: the body of buttons, inputs, sliders and dropdowns.
local function inset(props, children)
	props.Theme = props.Theme or { BackgroundColor3 = "Element" }
	return create("Frame", props, children)
end

-- Registers an element under its flag so it takes part in configs.
local function register(option, config)
	option.Flag = config.Flag
	if config.Flag then
		Library.Options[config.Flag] = option
		Library.Flags[config.Flag] = option.Value
	end
end

local function commit(option, callback, silent)
	if option.Flag then
		Library.Flags[option.Flag] = option.Value
	end
	if not silent then
		safeCall(callback, option.Value)
		safeCall(option._changed, option.Value)
	end
end

local function onChanged(option, fn)
	option._changed = fn
	return option
end

-- Lights a box's border while the pointer is over `button`.
local function hoverStroke(button, border, restKey)
	button.MouseEnter:Connect(function()
		tween(border, TWEEN_FAST, { Color = Library.Theme.Accent })
	end)
	button.MouseLeave:Connect(function()
		tween(border, TWEEN_FAST, { Color = Library.Theme[restKey or "Stroke"] })
	end)
end

-- `wrap` lets the text run over several lines instead of being cut off.
function Elements:AddLabel(text, wrap)
	local row = makeRow(self, 10)
	local text_ = label({
		Size = UDim2.fromScale(1, 1),
		Text = text or "",
		TextTruncate = Enum.TextTruncate.AtEnd,
		Theme = { TextColor3 = "SubText" },
		Parent = row,
	})
	local option = { Type = "Label", Instance = row, TextLabel = text_ }
	function option:Set(value)
		text_.Text = tostring(value)
	end
	function option:SetWrapped(on)
		if on then
			row.AutomaticSize = Enum.AutomaticSize.Y
			row.Size = UDim2.new(1, 0, 0, 10)
			text_.AutomaticSize = Enum.AutomaticSize.Y
			text_.Size = UDim2.new(1, 0, 0, 10)
			text_.TextWrapped = true
			text_.TextTruncate = Enum.TextTruncate.None
			text_.TextYAlignment = Enum.TextYAlignment.Top
			text_.LineHeight = 1.4
		else
			row.AutomaticSize = Enum.AutomaticSize.None
			row.Size = UDim2.new(1, 0, 0, 10)
			text_.AutomaticSize = Enum.AutomaticSize.None
			text_.Size = UDim2.fromScale(1, 1)
			text_.TextWrapped = false
			text_.TextTruncate = Enum.TextTruncate.AtEnd
			text_.TextYAlignment = Enum.TextYAlignment.Center
			text_.LineHeight = 1
		end
	end
	if wrap then
		option:SetWrapped(true)
	end
	return option
end

function Elements:AddParagraph(config)
	config = config or {}
	local row = makeRow(self, 0)
	row.AutomaticSize = Enum.AutomaticSize.Y
	create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 6), Parent = row })
	local title = label({
		LayoutOrder = 1,
		Size = UDim2.new(1, 0, 0, 8),
		Text = config.Title or "",
		Theme = { TextColor3 = "Accent" },
		Parent = row,
	})
	local body = label({
		LayoutOrder = 2,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LineHeight = 1.4,
		TextWrapped = true,
		TextYAlignment = Enum.TextYAlignment.Top,
		Text = config.Content or "",
		Theme = { TextColor3 = "SubText" },
		Parent = row,
	})
	local option = { Type = "Paragraph", Instance = row }
	function option:Set(newConfig)
		title.Text = newConfig.Title or title.Text
		body.Text = newConfig.Content or body.Text
	end
	return option
end

-- A thin rule with a blossom in the middle.
function Elements:AddDivider()
	local row = makeRow(self, 9)
	create("Frame", {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Size = UDim2.new(0.5, -9, 0, 1),
		Theme = { BackgroundColor3 = "Stroke" },
		Parent = row,
	})
	create("Frame", {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.fromScale(1, 0.5),
		Size = UDim2.new(0.5, -9, 0, 1),
		Theme = { BackgroundColor3 = "Stroke" },
		Parent = row,
	})
	local bloom = sprite(SPRITES.bloom, 1)
	bloom.AnchorPoint = CENTER
	bloom.Position = UDim2.fromScale(0.5, 0.5)
	bloom.Parent = row
end

function Elements:AddButton(config)
	config = config or {}
	local row = makeRow(self, 22)
	local border = stroke()
	local box = inset({
		Position = UDim2.fromOffset(1, 1),
		Size = UDim2.new(1, -2, 1, -2),
		Parent = row,
	}, { border })
	local title = label({
		Size = UDim2.fromScale(1, 1),
		TextXAlignment = Enum.TextXAlignment.Center,
		Text = config.Name or "Button",
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = box,
	})
	local button = clickArea(row)
	hoverStroke(button, border)
	button.MouseButton1Click:Connect(function()
		box.BackgroundColor3 = Library.Theme.Accent
		tween(box, TWEEN_MED, { BackgroundColor3 = Library.Theme.Element })
		safeCall(config.Callback)
	end)

	local option = { Type = "Button", Instance = row }
	function option:SetName(name)
		title.Text = name
	end
	function option:Fire()
		safeCall(config.Callback)
	end
	return option
end

function Elements:AddToggle(config)
	config = config or {}
	local row = makeRow(self, 15)

	-- The checkbox blooms a pixel flower when it is switched on.
	local bloom = sprite(SPRITES.bloom, 1, BLOOM_WHITE)
	bloom.AnchorPoint = CENTER
	bloom.Position = UDim2.fromScale(0.5, 0.5)
	local bloomScale = create("UIScale", { Scale = 0, Parent = bloom })
	local border = stroke(false)
	local box = create("Frame", {
		Position = UDim2.fromOffset(1, 1),
		Size = UDim2.fromOffset(13, 13),
		Parent = row,
	}, { border, bloom })
	local glow = addGlow(box, "element")
	local title = label({
		Position = UDim2.fromOffset(23, 0),
		Size = UDim2.new(1, -23, 1, 0),
		Text = config.Name or "Toggle",
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = row,
	})

	local option = { Type = "Toggle", Value = config.Default == true, Instance = row }
	local hovered = false

	local function render(animated)
		local theme = Library.Theme
		local on = option.Value
		apply(box, animated, TWEEN_FAST, { BackgroundColor3 = on and theme.Accent or theme.Element })
		apply(border, animated, TWEEN_FAST, { Color = (on or hovered) and theme.Accent or theme.Stroke })
		apply(title, animated, TWEEN_FAST, { TextColor3 = on and theme.Text or theme.SubText })
		apply(bloomScale, animated, TWEEN_POP, { Scale = on and 1 or 0 })
		setGlowOn(glow, on)
	end

	function option:Set(value, silent)
		self.Value = value == true
		render(true)
		commit(self, config.Callback, silent)
	end
	option.OnChanged = onChanged

	local button = clickArea(row)
	button.MouseEnter:Connect(function()
		hovered = true
		render(true)
	end)
	button.MouseLeave:Connect(function()
		hovered = false
		render(true)
	end)
	button.MouseButton1Click:Connect(function()
		option:Set(not option.Value)
	end)

	onTheme(function()
		render(false)
	end)
	register(option, config)
	if option.Value then
		safeCall(config.Callback, true)
	end
	return option
end

function Elements:AddSlider(config)
	config = config or {}
	local min, max = config.Min or 0, config.Max or 100
	local step = config.Increment or 1
	local suffix = config.Suffix or ""

	local row = makeRow(self, 28)
	label({
		Size = UDim2.new(1, -100, 0, 10),
		Text = config.Name or "Slider",
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = row,
	})
	local valueLabel = label({
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, 0, 0, 0),
		Size = UDim2.new(0, 100, 0, 10),
		TextXAlignment = Enum.TextXAlignment.Right,
		Theme = { TextColor3 = "Accent" },
		Parent = row,
	})

	local fill = create("Frame", {
		Size = UDim2.fromScale(0, 1),
		Theme = { BackgroundColor3 = "Accent" },
	})
	setGlowOn(addGlow(fill, "element"), true)
	-- The handle is a blossom riding the end of the fill.
	local knob, knobParts = sprite(SPRITES.bloom, 1, BLOOM_WHITE)
	knob.AnchorPoint = CENTER
	knob.Position = UDim2.fromScale(0, 0.5)
	knob.ZIndex = 3
	onTheme(function(theme)
		for _, petal in ipairs(knobParts.P) do
			petal.BackgroundColor3 = theme.Knob
		end
	end)
	local border = stroke()
	local bar = inset({
		Position = UDim2.fromOffset(4, 17),
		Size = UDim2.new(1, -8, 0, 7),
		Parent = row,
	}, { border, fill, knob })
	-- Taller invisible hit area so the thin bar is easy to grab.
	local hit = create("TextButton", {
		Position = UDim2.fromOffset(0, 11),
		Size = UDim2.new(1, 0, 0, 17),
		BackgroundTransparency = 1,
		Text = "",
		AutoButtonColor = false,
		ZIndex = 5,
		Parent = row,
	})
	hoverStroke(hit, border)

	local option = { Type = "Slider", Value = min, Instance = row }

	function option:Set(value, silent)
		value = math.clamp(round(tonumber(value) or min, step), min, max)
		self.Value = value
		valueLabel.Text = config.Format and tostring(config.Format(value)) or (tostring(value) .. suffix)
		local alpha = max > min and (value - min) / (max - min) or 0
		tween(fill, TWEEN_FAST, { Size = UDim2.fromScale(alpha, 1) })
		tween(knob, TWEEN_FAST, { Position = UDim2.fromScale(alpha, 0.5) })
		commit(self, config.Callback, silent)
	end
	option.OnChanged = onChanged

	local function fromPointer(position)
		local alpha = math.clamp((position.X - bar.AbsolutePosition.X) / math.max(bar.AbsoluteSize.X, 1), 0, 1)
		local value = math.clamp(round(min + (max - min) * alpha, step), min, max)
		if value ~= option.Value then
			option:Set(value)
		end
	end

	hit.InputBegan:Connect(function(input)
		if isPress(input) then
			fromPointer(input.Position)
			trackDrag(input, fromPointer)
		end
	end)

	option:Set(config.Default or min, true)
	register(option, config)
	return option
end

function Elements:AddTextbox(config)
	config = config or {}
	local row = makeRow(self, 36)
	label({
		Size = UDim2.new(1, 0, 0, 10),
		Text = config.Name or "Textbox",
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = row,
	})
	local border = stroke()
	local box = create("TextBox", {
		Position = UDim2.fromOffset(1, 15),
		Size = UDim2.new(1, -2, 0, 20),
		Font = FONT,
		TextSize = TEXT,
		TextXAlignment = Enum.TextXAlignment.Left,
		Text = config.Default or "",
		PlaceholderText = config.Placeholder or "...",
		ClearTextOnFocus = false,
		ClipsDescendants = true,
		Theme = { BackgroundColor3 = "Element", TextColor3 = "Text", PlaceholderColor3 = "SubText" },
		Parent = row,
	}, { border, padding(0, 8) })

	local option = { Type = "Textbox", Value = config.Default or "", Instance = row }

	function option:Set(value, silent)
		value = tostring(value)
		if config.Numeric then
			value = tostring(tonumber(value) or tonumber(self.Value) or 0)
		end
		self.Value = value
		box.Text = value
		commit(self, config.Callback, silent)
	end
	option.OnChanged = onChanged

	box.Focused:Connect(function()
		tween(border, TWEEN_FAST, { Color = Library.Theme.Accent })
	end)
	box.FocusLost:Connect(function(enterPressed)
		tween(border, TWEEN_FAST, { Color = Library.Theme.Stroke })
		if config.RequireEnter and not enterPressed then
			box.Text = option.Value
			return
		end
		option:Set(box.Text)
	end)

	register(option, config)
	return option
end

function Elements:AddKeybind(config)
	config = config or {}
	local row = makeRow(self, 20)
	label({
		Size = UDim2.new(1, -112, 1, 0),
		Text = config.Name or "Keybind",
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = row,
	})
	local border = stroke()
	local keyLabel = create("TextButton", {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -1, 0.5, 0),
		Size = UDim2.fromOffset(104, 18),
		Font = FONT,
		TextSize = TEXT,
		AutoButtonColor = false,
		Theme = { BackgroundColor3 = "Element", TextColor3 = "SubText" },
		Parent = row,
	}, { border })
	hoverStroke(keyLabel, border)

	-- Value is a KeyCode name ("None" when unbound) so it serialises cleanly.
	local option = { Type = "Keybind", Value = "None", Instance = row }

	function option:Set(key, silent)
		if typeof(key) == "EnumItem" then
			key = key.Name
		end
		if type(key) ~= "string" or key == "Unknown" or not pcall(function()
			return Enum.KeyCode[key]
		end) then
			key = "None"
		end
		self.Value = key
		keyLabel.Text = "[" .. key .. "]"
		if self.Flag then
			Library.Flags[self.Flag] = key
		end
		if not silent then
			safeCall(config.ChangedCallback, key)
			safeCall(self._changed, key)
		end
	end
	option.OnChanged = onChanged

	keyLabel.MouseButton1Click:Connect(function()
		if Library._listening then
			return
		end
		Library._listening = true
		keyLabel.Text = "[...]"
		local conn
		conn = UserInputService.InputBegan:Connect(function(input)
			if input.UserInputType ~= Enum.UserInputType.Keyboard then
				return
			end
			conn:Disconnect()
			local key = input.KeyCode
			if key == Enum.KeyCode.Escape or key == Enum.KeyCode.Backspace then
				option:Set("None")
			else
				option:Set(key)
			end
			-- Release on the next frame so this same press does not fire the bind.
			task.defer(function()
				Library._listening = false
			end)
		end)
	end)

	connect(UserInputService.InputBegan, function(input, processed)
		if processed or Library._listening or option.Value == "None" then
			return
		end
		if input.KeyCode.Name == option.Value then
			safeCall(config.Callback, option.Value)
		end
	end)

	option:Set(config.Default or "None", true)
	register(option, config)
	return option
end

function Elements:AddDropdown(config)
	config = config or {}
	local multi = config.Multi == true
	local options = config.Options or {}
	local ITEM_HEIGHT, MAX_VISIBLE, CLOSED = 18, 6, 36

	local row = makeRow(self, CLOSED)
	row.ClipsDescendants = true
	label({
		Size = UDim2.new(1, 0, 0, 10),
		Text = config.Name or "Dropdown",
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = row,
	})
	local border = stroke()
	local box = inset({
		Position = UDim2.fromOffset(1, 15),
		Size = UDim2.new(1, -2, 0, 20),
		Parent = row,
	}, { border })
	local valueLabel = label({
		Position = UDim2.fromOffset(8, 0),
		Size = UDim2.new(1, -30, 1, 0),
		TextTruncate = Enum.TextTruncate.AtEnd,
		Theme = { TextColor3 = "SubText" },
		Parent = box,
	})
	local arrow = label({
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -8, 0, 0),
		Size = UDim2.new(0, 8, 1, 0),
		Text = "v",
		Theme = { TextColor3 = "Accent" },
		Parent = box,
	})
	local header = clickArea(box)
	hoverStroke(header, border)

	local list = create("ScrollingFrame", {
		Position = UDim2.fromOffset(1, 39),
		Size = UDim2.new(1, -2, 0, 0),
		ScrollBarThickness = 2,
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		Theme = { BackgroundColor3 = "Element", ScrollBarImageColor3 = "Accent" },
		Parent = row,
	}, {
		stroke(),
		create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }),
	})

	local option = { Type = "Dropdown", Value = multi and {} or nil, Instance = row }
	local open = false
	local items = {}

	local function isSelected(name)
		if multi then
			return table.find(option.Value, name) ~= nil
		end
		return option.Value == name
	end

	local function render()
		local theme = Library.Theme
		if multi then
			valueLabel.Text = #option.Value > 0 and table.concat(option.Value, ", ") or "none"
		else
			valueLabel.Text = option.Value ~= nil and tostring(option.Value) or "none"
		end
		for name, item in pairs(items) do
			local selected = isSelected(name)
			item.TextColor3 = selected and theme.Accent or theme.SubText
			item.BackgroundColor3 = theme.ElementHover
			item.BackgroundTransparency = selected and 0 or 1
		end
	end

	local function resize()
		local visible = math.min(#options, MAX_VISIBLE)
		local listHeight = visible * ITEM_HEIGHT
		list.Size = UDim2.new(1, -2, 0, listHeight)
		tween(row, TWEEN_MED, { Size = UDim2.new(1, 0, 0, open and (CLOSED + 4 + listHeight + 2) or CLOSED) })
		arrow.Text = open and "^" or "v"
	end

	function option:Set(value, silent)
		if multi then
			local picked = {}
			if type(value) == "table" then
				for _, name in ipairs(value) do
					if table.find(options, name) and not table.find(picked, name) then
						table.insert(picked, name)
					end
				end
			end
			self.Value = picked
		else
			self.Value = table.find(options, value) and value or nil
		end
		render()
		commit(self, config.Callback, silent)
	end
	option.OnChanged = onChanged

	local function build()
		for _, item in pairs(items) do
			item:Destroy()
		end
		items = {}
		for index, name in ipairs(options) do
			local item = create("TextButton", {
				LayoutOrder = index,
				Size = UDim2.new(1, 0, 0, ITEM_HEIGHT),
				Font = FONT,
				TextSize = TEXT,
				Text = tostring(name),
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				AutoButtonColor = false,
				Parent = list,
			}, { padding(0, 8) })
			item.MouseButton1Click:Connect(function()
				if multi then
					local picked = table.clone(option.Value)
					local at = table.find(picked, name)
					if at then
						table.remove(picked, at)
					else
						table.insert(picked, name)
					end
					option:Set(picked)
				else
					option:Set(name)
					open = false
					resize()
				end
			end)
			items[name] = item
		end
		render()
	end

	-- Replaces the option list, dropping selections that no longer exist.
	function option:Refresh(newOptions)
		options = newOptions or {}
		build()
		self:Set(self.Value, true)
		resize()
	end

	header.MouseButton1Click:Connect(function()
		open = not open
		resize()
	end)

	onTheme(render)
	build()
	option:Set(config.Default, true)
	register(option, config)
	return option
end

function Elements:AddColorPicker(config)
	config = config or {}
	local default = config.Default or Color3.fromRGB(255, 255, 255)
	local h, s, v = default:ToHSV()
	local CLOSED, OPEN = 16, 134

	local row = makeRow(self, CLOSED)
	row.ClipsDescendants = true
	label({
		Size = UDim2.new(1, -44, 0, CLOSED),
		Text = config.Name or "Color",
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = row,
	})
	local border = stroke()
	local swatch = create("Frame", {
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -1, 0, 2),
		Size = UDim2.fromOffset(34, 12),
		Parent = row,
	}, { border })
	local header = clickArea(row)
	header.Size = UDim2.new(1, 0, 0, CLOSED)
	hoverStroke(header, border)

	-- Saturation/value square: hue colour underneath, a white fade across and
	-- a black fade down, so no image assets are needed.
	local svCursor = create("Frame", {
		AnchorPoint = CENTER,
		Size = UDim2.fromOffset(5, 5),
		BackgroundColor3 = WHITE,
		ZIndex = 3,
	}, { create("UIStroke", { Color = BLACK, Thickness = 1 }) })
	local svBox = create("TextButton", {
		Position = UDim2.fromOffset(1, 22),
		Size = UDim2.new(1, -2, 0, 90),
		Text = "",
		AutoButtonColor = false,
		Parent = row,
	}, {
		stroke(),
		create("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = WHITE }, {
			create("UIGradient", {
				Transparency = NumberSequence.new(0, 1),
			}),
		}),
		create("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = BLACK, ZIndex = 2 }, {
			create("UIGradient", {
				Rotation = 90,
				Transparency = NumberSequence.new(1, 0),
			}),
		}),
		svCursor,
	})

	local hueKeys = {}
	for i = 0, 6 do
		table.insert(hueKeys, ColorSequenceKeypoint.new(i / 6, Color3.fromHSV(i / 6, 1, 1)))
	end
	local hueCursor = create("Frame", {
		AnchorPoint = CENTER,
		Position = UDim2.fromScale(0, 0.5),
		Size = UDim2.new(0, 3, 1, 4),
		BackgroundColor3 = WHITE,
	}, { create("UIStroke", { Color = BLACK, Thickness = 1 }) })
	local hueBar = create("TextButton", {
		Position = UDim2.fromOffset(1, 120),
		Size = UDim2.new(1, -2, 0, 10),
		BackgroundColor3 = WHITE,
		Text = "",
		AutoButtonColor = false,
		Parent = row,
	}, { stroke(), create("UIGradient", { Color = ColorSequence.new(hueKeys) }), hueCursor })

	local option = { Type = "ColorPicker", Value = default, Instance = row }

	local function update(silent)
		option.Value = Color3.fromHSV(h, s, v)
		swatch.BackgroundColor3 = option.Value
		svBox.BackgroundColor3 = Color3.fromHSV(h, 1, 1)
		svCursor.Position = UDim2.fromScale(s, 1 - v)
		hueCursor.Position = UDim2.fromScale(h, 0.5)
		commit(option, config.Callback, silent)
	end

	function option:Set(color, silent)
		if type(color) == "string" then
			color = hexToColor(color)
		end
		if typeof(color) ~= "Color3" then
			return
		end
		h, s, v = color:ToHSV()
		update(silent)
	end
	option.OnChanged = onChanged

	local function dragSV(position)
		s = math.clamp((position.X - svBox.AbsolutePosition.X) / math.max(svBox.AbsoluteSize.X, 1), 0, 1)
		v = 1 - math.clamp((position.Y - svBox.AbsolutePosition.Y) / math.max(svBox.AbsoluteSize.Y, 1), 0, 1)
		update()
	end
	local function dragHue(position)
		h = math.clamp((position.X - hueBar.AbsolutePosition.X) / math.max(hueBar.AbsoluteSize.X, 1), 0, 1)
		update()
	end
	svBox.InputBegan:Connect(function(input)
		if isPress(input) then
			dragSV(input.Position)
			trackDrag(input, dragSV)
		end
	end)
	hueBar.InputBegan:Connect(function(input)
		if isPress(input) then
			dragHue(input.Position)
			trackDrag(input, dragHue)
		end
	end)

	local open = false
	header.MouseButton1Click:Connect(function()
		open = not open
		tween(row, TWEEN_MED, { Size = UDim2.new(1, 0, 0, open and OPEN or CLOSED) })
	end)

	update(true)
	register(option, config)
	return option
end

---------------------------------------------------------------------
-- Groupboxes, sub-tabs and tabs
---------------------------------------------------------------------

local Groupbox = setmetatable({}, Elements)
Groupbox.__index = Groupbox

local SubTab = {}
SubTab.__index = SubTab

local Tab = {}
Tab.__index = Tab

local COLUMN_GAP = 12
local HEADER_BLOOMS = { BLOOM_PINK, BLOOM_WHITE, BLOOM_ROSE }

-- `column` counts from the left, starting at 1.
function SubTab:AddGroupbox(name, column)
	column = math.clamp(math.floor(tonumber(column) or 1), 1, #self._columns)
	self._counts[column] = (self._counts[column] or 0) + 1
	self._total = (self._total or 0) + 1

	local icon = sprite(SPRITES.bloomShaded, 2, HEADER_BLOOMS[(self._total - 1) % #HEADER_BLOOMS + 1])
	icon.AnchorPoint = Vector2.new(0, 0.5)
	icon.Position = UDim2.new(0, 8, 0.5, 0)
	local topLine = create("Frame", {
		LayoutOrder = 1,
		Size = UDim2.new(1, 0, 0, 2),
		Theme = { BackgroundColor3 = "Accent" },
	})
	setGlowOn(addGlow(topLine, "element"), true)
	local body = create("Frame", {
		LayoutOrder = 3,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
	}, {
		padding(3, 10, 11, 10),
		create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 8) }),
	})
	local frame = create("Frame", {
		LayoutOrder = self._counts[column],
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Theme = { BackgroundColor3 = "Panel" },
		Parent = self._columns[column],
	}, {
		stroke(),
		create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }),
		topLine,
		create("Frame", {
			LayoutOrder = 2,
			Size = UDim2.new(1, 0, 0, 26),
			BackgroundTransparency = 1,
		}, {
			icon,
			label({
				Position = UDim2.fromOffset(30, 0),
				Size = UDim2.new(1, -40, 1, 0),
				Text = name or "groupbox",
				TextTruncate = Enum.TextTruncate.AtEnd,
				Theme = { TextColor3 = "Accent" },
			}),
		}),
		body,
	})
	glass(frame, "panel")
	return setmetatable({ Container = body, Instance = frame, _order = 0 }, Groupbox)
end

function SubTab:AddLeftGroupbox(name)
	return self:AddGroupbox(name, 1)
end

function SubTab:AddRightGroupbox(name)
	return self:AddGroupbox(name, #self._columns)
end

local Tabbox = {}
Tabbox.__index = Tabbox

-- A groupbox with a row of small tabs. Each tab (Tabbox:AddTab) is a groupbox body.
function SubTab:AddTabbox(column)
	column = math.clamp(math.floor(tonumber(column) or 1), 1, #self._columns)
	self._counts[column] = (self._counts[column] or 0) + 1
	local topLine = create("Frame", {
		LayoutOrder = 1,
		Size = UDim2.new(1, 0, 0, 2),
		Theme = { BackgroundColor3 = "Accent" },
	})
	setGlowOn(addGlow(topLine, "element"), true)
	local row = create("Frame", {
		LayoutOrder = 2,
		Size = UDim2.new(1, 0, 0, 22),
		BackgroundTransparency = 1,
	}, {
		create("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal,
			SortOrder = Enum.SortOrder.LayoutOrder,
		}),
	})
	local rule = create("Frame", {
		LayoutOrder = 3,
		Size = UDim2.new(1, 0, 0, 1),
		Theme = { BackgroundColor3 = "Stroke" },
	})
	local frame = create("Frame", {
		LayoutOrder = self._counts[column],
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Theme = { BackgroundColor3 = "Panel" },
		Parent = self._columns[column],
	}, {
		stroke(),
		create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }),
		topLine,
		row,
		rule,
	})
	glass(frame, "panel")
	return setmetatable({ Instance = frame, _row = row, _tabs = {} }, Tabbox)
end

function SubTab:AddLeftTabbox()
	return self:AddTabbox(1)
end

function SubTab:AddRightTabbox()
	return self:AddTabbox(#self._columns)
end

function Tabbox:AddTab(name)
	local tabbox = self
	local body = create("Frame", {
		LayoutOrder = 4,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Visible = false,
		Parent = self.Instance,
	}, {
		padding(8, 10, 11, 10),
		create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 8) }),
	})
	local underline = create("Frame", {
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.fromScale(0, 1),
		Size = UDim2.new(1, 0, 0, 1),
		Visible = false,
		Theme = { BackgroundColor3 = "Accent" },
	})
	local button = create("TextButton", {
		LayoutOrder = #self._tabs + 1,
		Size = UDim2.new(0, 0, 1, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 1,
		Font = FONT,
		TextSize = TEXT,
		Text = name or "tab",
		AutoButtonColor = false,
		Parent = self._row,
	}, { padding(0, 10), underline })
	local entry = { button = button, body = body, underline = underline, active = false }
	table.insert(self._tabs, entry)
	local function choose()
		for _, other in ipairs(tabbox._tabs) do
			local on = other == entry
			other.active = on
			other.body.Visible = on
			other.underline.Visible = on
			other.button.TextColor3 = on and Library.Theme.Accent or Library.Theme.SubText
		end
	end
	button.MouseButton1Click:Connect(choose)
	onTheme(function(theme)
		button.TextColor3 = entry.active and theme.Accent or theme.SubText
	end)
	if #self._tabs == 1 then
		choose()
	end
	return setmetatable({ Container = body, Instance = body, _order = 0 }, Groupbox)
end

-- `config` may be a name or { Name, Columns }.
function Tab:AddSubTab(config)
	if type(config) == "string" then
		config = { Name = config }
	end
	config = config or {}
	local tab = self
	local count = math.clamp(math.floor(config.Columns or self._window.Columns), 1, 4)

	local bullet = sprite(SPRITES.bloom, 1)
	bullet.AnchorPoint = Vector2.new(0, 0.5)
	bullet.Position = UDim2.new(0, -13, 0.5, 0)
	bullet.Visible = false
	local button = create("TextButton", {
		LayoutOrder = #self.SubTabs + 1,
		Size = UDim2.new(0, 0, 1, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 1,
		Font = FONT,
		TextSize = TEXT,
		Text = config.Name or "sub",
		AutoButtonColor = false,
		Parent = self._bar,
	}, { padding(0, 10, 0, 22), bullet })

	local page = create("Frame", {
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Visible = false,
		Parent = self._page,
	})
	local columns = {}
	for i = 1, count do
		columns[i] = create("ScrollingFrame", {
			Position = UDim2.new((i - 1) / count, COLUMN_GAP - (i - 1) * COLUMN_GAP / count, 0, 0),
			Size = UDim2.new(1 / count, -COLUMN_GAP * (count + 1) / count, 1, 0),
			BackgroundTransparency = 1,
			ScrollBarThickness = 2,
			CanvasSize = UDim2.new(),
			AutomaticCanvasSize = Enum.AutomaticSize.Y,
			ScrollingDirection = Enum.ScrollingDirection.Y,
			Theme = { ScrollBarImageColor3 = "Accent" },
			Parent = page,
		}, {
			padding(11, 6, 12, 1),
			create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 11) }),
		})
	end

	local sub = setmetatable({
		Name = config.Name,
		Instance = page,
		_tab = self,
		_button = button,
		_bullet = bullet,
		_columns = columns,
		_counts = {},
		_active = false,
	}, SubTab)
	table.insert(self.SubTabs, sub)

	button.MouseButton1Click:Connect(function()
		tab:SelectSubTab(sub)
	end)
	onTheme(function(theme)
		button.TextColor3 = sub._active and theme.Accent or theme.SubText
	end)

	if #self.SubTabs == 1 then
		self:SelectSubTab(sub, true)
	end
	return sub
end

-- `instant` skips the colour tween.
function Tab:SelectSubTab(sub, instant)
	for _, other in ipairs(self.SubTabs) do
		local active = other == sub
		other._active = active
		other.Instance.Visible = active
		other._bullet.Visible = active
		apply(other._button, not instant, TWEEN_FAST, {
			TextColor3 = active and Library.Theme.Accent or Library.Theme.SubText,
		})
	end
end

-- Groupboxes added straight to a tab go into a "general" sub-tab.
local function defaultSubTab(tab)
	if not tab._default then
		tab._default = tab:AddSubTab("general")
	end
	return tab._default
end

function Tab:AddGroupbox(name, column)
	return defaultSubTab(self):AddGroupbox(name, column)
end

function Tab:AddLeftGroupbox(name)
	return defaultSubTab(self):AddLeftGroupbox(name)
end

function Tab:AddRightGroupbox(name)
	return defaultSubTab(self):AddRightGroupbox(name)
end

function Tab:AddTabbox(column)
	return defaultSubTab(self):AddTabbox(column)
end

function Tab:AddLeftTabbox()
	return defaultSubTab(self):AddLeftTabbox()
end

function Tab:AddRightTabbox()
	return defaultSubTab(self):AddRightTabbox()
end

-- Runs `builder(tab)` the first time the tab is shown (at once if it already is), so
-- big tabs only cost anything when somebody opens them.
function Tab:SetBuilder(builder)
	self._builder = builder
	if self._active then
		self:_build()
	end
end

function Tab:_build()
	local builder = self._builder
	if not builder then
		return
	end
	self._builder = nil
	local ok, err = pcall(builder, self)
	if not ok then
		warn("[Sakura UI] tab builder failed: " .. tostring(err))
	end
end

---------------------------------------------------------------------
-- Window
---------------------------------------------------------------------

local Window = {}
Window.__index = Window

local TITLE_HEIGHT, TAB_HEIGHT, SUB_HEIGHT, STATUS_HEIGHT = 28, 24, 22, 22
local BORDER = 2 -- outline + accent line

function Library:CreateWindow(config)
	config = config or {}
	if config.Theme then
		self:SetTheme(config.Theme)
	end
	local size = config.Size or UDim2.fromOffset(920, 580)
	local pixel = math.max(1, math.floor(config.PixelSize or 4))
	local guis = getGuis()

	local window = setmetatable({
		Tabs = {},
		ToggleKey = config.ToggleKey or Enum.KeyCode.RightShift,
		ConfigFolder = config.ConfigFolder or "SakuraUI",
		Columns = config.Columns or 2,
		Visible = true,
		Minimized = false,
		_size = size,
		_roots = {},
	}, Window)

	local function root(gui, props)
		props.AnchorPoint = CENTER
		props.Position = UDim2.fromScale(0.5, 0.5)
		props.Size = size
		props.Parent = gui
		local frame = create("Frame", props)
		table.insert(window._roots, frame)
		return frame
	end

	-- Layer 1: an opaque slab whose UIShadow is the window glow.
	local glowRoot = root(guis.glow, { Name = "Glow", Theme = { BackgroundColor3 = "Outline" } })
	window._glow = addGlow(glowRoot, "window")

	-- Layer 2: outline, accent line and the pixel-art backdrop.
	local backRoot = root(guis.back, { Name = "Backdrop", Theme = { BackgroundColor3 = "Outline" } })
	create("Frame", {
		Position = UDim2.fromOffset(1, 1),
		Size = UDim2.new(1, -2, 1, -2),
		Theme = { BackgroundColor3 = "Accent" },
		Parent = backRoot,
	})
	local sceneClip = create("Frame", {
		Position = UDim2.fromOffset(BORDER, BORDER),
		Size = UDim2.new(1, -BORDER * 2, 1, -BORDER * 2),
		ClipsDescendants = true,
		Theme = { BackgroundColor3 = "Panel" },
		Parent = backRoot,
	})
	local built, scene = pcall(buildScene, sceneClip, pixel)
	if not built then
		warn("[Sakura UI] backdrop failed, using a plain panel: " .. tostring(scene))
		scene = { Instance = create("Frame", { BackgroundTransparency = 1, Parent = sceneClip }) }
		function scene:Recolor() end
	end
	window._scene = scene
	window.Backdrop = sceneClip -- clipped frame behind the controls (custom images go here)
	window._scene.Instance.Visible = config.Background ~= false

	-- Layer 3: the controls.
	local shell = root(guis.main, { Name = "Window", BackgroundTransparency = 1 })
	window.Instance = shell
	local content = create("Frame", {
		Position = UDim2.fromOffset(BORDER, BORDER),
		Size = UDim2.new(1, -BORDER * 2, 1, -BORDER * 2),
		BackgroundTransparency = 1,
		ClipsDescendants = true,
		Active = true, -- stop clicks falling through to the game
		Parent = shell,
	})
	window._content = content
	-- A visible modal button frees the mouse in first-person games.
	create("TextButton", {
		Size = UDim2.new(),
		BackgroundTransparency = 1,
		Text = "",
		Modal = true,
		Parent = shell,
	})

	-- Scale: whatever SetScale asks for, shrunk so the window fits the screen.
	window._userScale = 1
	window._scales = {}
	for _, frame in ipairs(window._roots) do
		table.insert(window._scales, create("UIScale", { Scale = 1, Parent = frame }))
	end
	local camera = workspace and workspace.CurrentCamera
	function window:_rescale()
		local fit = 2
		local current = self._size
		if camera and current.X.Offset > 0 and current.Y.Offset > 0 then
			local viewport = camera.ViewportSize
			fit = math.min((viewport.X - 24) / current.X.Offset, (viewport.Y - 24) / current.Y.Offset)
		end
		local value = math.clamp(math.min(self._userScale, fit), 0.4, 2)
		for _, scale in ipairs(self._scales) do
			scale.Scale = value
		end
	end
	window:_rescale()
	if camera then
		connect(camera:GetPropertyChangedSignal("ViewportSize"), function()
			window:_rescale()
		end)
	end

	local petalLayer = create("Frame", {
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		ZIndex = 1,
		Parent = content,
	})
	window._petals = startPetals(
		window,
		petalLayer,
		math.max(size.X.Offset, 200) - BORDER * 2,
		math.max(size.Y.Offset, 200) - BORDER * 2,
		pixel
	)
	-- Baked-blur crops sit between the petals and the panels (see SetFrost).
	window._frostLayer = create("Frame", {
		Name = "Frost",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Visible = false,
		ZIndex = 2,
		Parent = content,
	})
	if size.X.Scale == 0 and size.Y.Scale == 0 then
		window._frostSize = Vector2.new(size.X.Offset - BORDER * 2, size.Y.Offset - BORDER * 2)
	end

	-- Title bar -----------------------------------------------------
	local titleBar = create("Frame", {
		Size = UDim2.new(1, 0, 0, TITLE_HEIGHT),
		ZIndex = 4,
		Theme = { BackgroundColor3 = "Header" },
		Parent = content,
	})
	glass(titleBar, "header")
	local icon = sprite(SPRITES.sakura, 2)
	icon.AnchorPoint = Vector2.new(0, 0.5)
	icon.Position = UDim2.new(0, 7, 0.5, 0)
	icon.Parent = titleBar
	if type(config.Logo) == "table" then
		self:SetLogo(config.Logo)
	end
	local logo = config.Logo and self:CreateLogo(config.LogoHeight or 34, titleBar)
	if logo then
		logo.AnchorPoint = Vector2.new(0, 0.5)
		logo.Position = UDim2.new(0, 30, 0.5, 0)
		window._logo = logo
	else
		local title = label({
			Position = UDim2.fromOffset(38, 0),
			Size = UDim2.new(0, 0, 1, 0),
			AutomaticSize = Enum.AutomaticSize.X,
			Text = config.Title or "sakura ui",
			Parent = titleBar,
		})
		addGlow(title, "text")
	end
	if config.SubTitle then
		label({
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, -62, 0, 0),
			Size = UDim2.new(0.5, 0, 1, 0),
			TextXAlignment = Enum.TextXAlignment.Right,
			Text = config.SubTitle,
			Theme = { TextColor3 = "SubText" },
			Parent = titleBar,
		})
	end

	local function topButton(text, offset, callback)
		local border = stroke()
		local button = create("TextButton", {
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, offset, 0.5, 0),
			Size = UDim2.fromOffset(18, 16),
			Font = FONT,
			TextSize = TEXT,
			Text = text,
			AutoButtonColor = false,
			Theme = { BackgroundColor3 = "Element", TextColor3 = "Text" },
			Parent = titleBar,
		}, { border })
		hoverStroke(button, border)
		button.MouseButton1Click:Connect(callback)
		return button
	end
	topButton("x", -7, function()
		window:SetVisible(false)
	end)
	topButton("-", -31, function()
		window:SetMinimized(not window.Minimized)
	end)

	-- Dragging ------------------------------------------------------
	titleBar.InputBegan:Connect(function(input)
		if not isPress(input) then
			return
		end
		local origin = input.Position
		local start = shell.Position
		trackDrag(input, function(position)
			local delta = position - origin
			local moved = UDim2.new(start.X.Scale, start.X.Offset + delta.X, start.Y.Scale, start.Y.Offset + delta.Y)
			for _, frame in ipairs(window._roots) do
				frame.Position = moved
			end
		end)
	end)

	-- Resizing: drag the grip in the bottom-right corner -------------
	window.MinSize = config.MinSize or Vector2.new(640, 400)
	if config.Resizable ~= false and size.X.Scale == 0 and size.Y.Scale == 0 then
		local grip = create("TextButton", {
			Name = "ResizeGrip",
			AnchorPoint = Vector2.new(1, 1),
			Position = UDim2.new(1, -1, 1, -1),
			Size = UDim2.fromOffset(16, 16),
			BackgroundTransparency = 1,
			Text = "",
			AutoButtonColor = false,
			ZIndex = 20,
			Parent = shell,
		})
		-- a little pixel staircase
		local dots = {}
		for i, spot in ipairs({ { 12, 4 }, { 8, 8 }, { 12, 8 }, { 4, 12 }, { 8, 12 }, { 12, 12 } }) do
			dots[i] = create("Frame", {
				Position = UDim2.fromOffset(spot[1] - 2, spot[2] - 2),
				Size = UDim2.fromOffset(2, 2),
				BackgroundTransparency = 0.35,
				Theme = { BackgroundColor3 = "Accent" },
				Parent = grip,
			})
		end
		grip.MouseEnter:Connect(function()
			for _, dot in ipairs(dots) do
				dot.BackgroundTransparency = 0
			end
		end)
		grip.MouseLeave:Connect(function()
			for _, dot in ipairs(dots) do
				dot.BackgroundTransparency = 0.35
			end
		end)
		grip.InputBegan:Connect(function(input)
			if not isPress(input) or window.Minimized then
				return
			end
			local origin = input.Position
			local startSize = window._size
			local scale = window._scales[1] and window._scales[1].Scale or 1
			trackDrag(input, function(position)
				local delta = position - origin
				window:SetSize(startSize.X.Offset + delta.X / scale, startSize.Y.Offset + delta.Y / scale)
			end, function()
				if window.OnResized then
					task.spawn(window.OnResized, window._size.X.Offset, window._size.Y.Offset)
				end
			end)
		end)
		window._grip = grip
	end

	-- Tab bar, sub-tab bar and pages ---------------------------------
	local tabBar = create("Frame", {
		Position = UDim2.fromOffset(0, TITLE_HEIGHT),
		Size = UDim2.new(1, 0, 0, TAB_HEIGHT),
		ZIndex = 4,
		Theme = { BackgroundColor3 = "Header" },
		Parent = content,
	})
	glass(tabBar, "header")
	create("Frame", {
		Size = UDim2.new(1, 0, 0, 1),
		Theme = { BackgroundColor3 = "Stroke" },
		Parent = tabBar,
	})
	window._tabList = create("Frame", {
		Position = UDim2.fromOffset(0, 1),
		Size = UDim2.new(1, 0, 1, -1),
		BackgroundTransparency = 1,
		Parent = tabBar,
	}, {
		padding(0, 6),
		create("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal,
			SortOrder = Enum.SortOrder.LayoutOrder,
		}),
	})

	local subBar = create("Frame", {
		Position = UDim2.fromOffset(0, TITLE_HEIGHT + TAB_HEIGHT),
		Size = UDim2.new(1, 0, 0, SUB_HEIGHT),
		ZIndex = 4,
		Theme = { BackgroundColor3 = "Panel" },
		Parent = content,
	})
	glass(subBar, "panel")
	create("Frame", {
		Size = UDim2.new(1, 0, 0, 1),
		Theme = { BackgroundColor3 = "Accent" },
		Parent = subBar,
	})
	create("Frame", {
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.fromScale(0, 1),
		Size = UDim2.new(1, 0, 0, 1),
		Theme = { BackgroundColor3 = "Stroke" },
		Parent = subBar,
	})
	window._subBar = subBar

	local top = TITLE_HEIGHT + TAB_HEIGHT + SUB_HEIGHT
	window._pages = create("Frame", {
		Position = UDim2.fromOffset(0, top),
		Size = UDim2.new(1, 0, 1, -top - STATUS_HEIGHT),
		BackgroundTransparency = 1,
		ZIndex = 3,
		Parent = content,
	})

	-- Status bar ----------------------------------------------------
	local statusBar = create("Frame", {
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.fromScale(0, 1),
		Size = UDim2.new(1, 0, 0, STATUS_HEIGHT),
		ZIndex = 4,
		Theme = { BackgroundColor3 = "Header" },
		Parent = content,
	})
	glass(statusBar, "header")
	create("Frame", {
		Size = UDim2.new(1, 0, 0, 1),
		Theme = { BackgroundColor3 = "Stroke" },
		Parent = statusBar,
	})
	local rose = sprite(SPRITES.rose, 2)
	rose.AnchorPoint = Vector2.new(0, 0.5)
	rose.Position = UDim2.new(0, 7, 0.5, 1)
	rose.Parent = statusBar
	label({
		Position = UDim2.fromOffset(33, 0),
		Size = UDim2.new(0.6, -33, 1, 0),
		Text = config.Footer or ("sakura ui v" .. Library.Version),
		TextTruncate = Enum.TextTruncate.AtEnd,
		Theme = { TextColor3 = "SubText" },
		Parent = statusBar,
	})
	window._hint = label({
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -22, 0, 0),
		Size = UDim2.new(0.4, -8, 1, 0),
		TextXAlignment = Enum.TextXAlignment.Right,
		Theme = { TextColor3 = "SubText" },
		Parent = statusBar,
	})
	window:SetToggleKey(window.ToggleKey)

	-- Toggle key ------------------------------------------------------
	connect(UserInputService.InputBegan, function(input, processed)
		if processed or Library._listening then
			return
		end
		if input.KeyCode == window.ToggleKey and input.KeyCode ~= Enum.KeyCode.Unknown then
			window:SetVisible(not window.Visible)
		end
	end)

	-- Touch devices have no toggle key, so give them a button.
	if UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled then
		local mobile = create("TextButton", {
			Position = UDim2.new(0, 12, 0.5, -20),
			Size = UDim2.fromOffset(40, 40),
			Text = "",
			AutoButtonColor = false,
			Theme = { BackgroundColor3 = "Header" },
			Parent = guis.main,
		}, { stroke("Accent") })
		local flower = sprite(SPRITES.sakura, 2)
		flower.AnchorPoint = CENTER
		flower.Position = UDim2.fromScale(0.5, 0.5)
		flower.Parent = mobile
		mobile.MouseButton1Click:Connect(function()
			window:SetVisible(not window.Visible)
		end)
	end

	-- Glow pulse: breathe the window glow's opacity.
	local clock = 0
	connect(RunService.Heartbeat, function(dt)
		if not window.Visible then
			return
		end
		soft("frost", updateFrost, window)
		local settings = Library.Glow
		if not settings.Pulse then
			return
		end
		clock = clock + dt
		local pulse = 0.8 + 0.2 * math.sin(clock * 2.4)
		if window._glow and settings.Enabled then
			applyGlow(window._glow, pulse)
		end
		for _, entry in ipairs(glows) do
			if entry.kind == "logo" then
				applyGlow(entry, pulse)
			end
		end
	end)

	table.insert(self._windows, window)

	-- Intro animation
	for _, frame in ipairs(window._roots) do
		frame.Size = UDim2.new(size.X.Scale, size.X.Offset, 0, TITLE_HEIGHT + BORDER * 2)
		tween(frame, TWEEN_MED, { Size = size })
	end

	return window
end

-- Window scale in percent (40-200). It still shrinks to fit the screen.
function Window:SetScale(percent)
	self._userScale = math.clamp((tonumber(percent) or 100) / 100, 0.4, 2)
	self:_rescale()
end

function Window:SetVisible(visible)
	self.Visible = visible
	for _, frame in ipairs(self._roots) do
		frame.Visible = visible
	end
end

function Window:Toggle()
	self:SetVisible(not self.Visible)
end

function Window:SetMinimized(minimized)
	self.Minimized = minimized
	local size = self._size
	local target = minimized and UDim2.new(size.X.Scale, size.X.Offset, 0, TITLE_HEIGHT + BORDER * 2) or size
	for _, frame in ipairs(self._roots) do
		tween(frame, TWEEN_MED, { Size = target })
	end
end

-- Resizes the window (pixels, before UI scale), keeping its top-left corner in place.
function Window:SetSize(width, height)
	local min = self.MinSize or Vector2.new(640, 400)
	local maxW, maxH = 4000, 3000
	local camera = workspace and workspace.CurrentCamera
	local scale = self._scales[1] and self._scales[1].Scale or 1
	if camera and scale > 0 then
		maxW = math.max(min.X, (camera.ViewportSize.X - 8) / scale)
		maxH = math.max(min.Y, (camera.ViewportSize.Y - 8) / scale)
	end
	width = math.floor(math.clamp(tonumber(width) or min.X, min.X, maxW) + 0.5)
	height = math.floor(math.clamp(tonumber(height) or min.Y, min.Y, maxH) + 0.5)
	local old = self._size
	local dw, dh = width - old.X.Offset, height - old.Y.Offset
	if dw == 0 and dh == 0 then
		return
	end
	self._size = UDim2.fromOffset(width, height)
	for _, frame in ipairs(self._roots) do
		local pos = frame.Position
		-- roots are centre-anchored: shift by half the growth to keep the corner put
		frame.Position = UDim2.new(pos.X.Scale, pos.X.Offset + dw * scale / 2, pos.Y.Scale, pos.Y.Offset + dh * scale / 2)
		if not self.Minimized then
			frame.Size = self._size
		end
	end
	self._frostSize = Vector2.new(width - BORDER * 2, height - BORDER * 2)
	if self._petals and self._petals.SetBounds then
		self._petals:SetBounds(width - BORDER * 2, height - BORDER * 2)
	end
end

function Window:GetSize()
	return self._size.X.Offset, self._size.Y.Offset
end

-- Shows or hides the pixel-art backdrop (a plain panel colour is left behind).
function Window:SetBackground(enabled)
	self._scene.Instance.Visible = enabled == true
end

function Window:SetToggleKey(key)
	if type(key) == "string" then
		local ok, code = pcall(function()
			return Enum.KeyCode[key]
		end)
		key = ok and code or Enum.KeyCode.Unknown
	end
	self.ToggleKey = key or Enum.KeyCode.Unknown
	if self.ToggleKey == Enum.KeyCode.Unknown then
		self._hint.Text = ""
	else
		self._hint.Text = "[" .. self.ToggleKey.Name .. "] hide"
	end
end

-- `instant` skips the colour tween.
function Window:SelectTab(tab, instant)
	for _, other in ipairs(self.Tabs) do
		local active = other == tab
		other._active = active
		other._page.Visible = active
		other._bar.Visible = active
		other._underline.Visible = active
		apply(other._button, not instant, TWEEN_FAST, {
			BackgroundTransparency = active and 0.35 or 1,
			TextColor3 = active and Library.Theme.Text or Library.Theme.SubText,
		})
	end
	if tab and tab._builder then
		tab:_build()
	end
end

function Window:AddTab(config)
	if type(config) == "string" then
		config = { Name = config }
	end
	config = config or {}
	local window = self

	local underline = create("Frame", {
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.new(0, -12, 1, 0),
		Size = UDim2.new(1, 24, 0, 2),
		Visible = false,
		Theme = { BackgroundColor3 = "Accent" },
	})
	setGlowOn(addGlow(underline, "element"), true)
	local button = create("TextButton", {
		LayoutOrder = #self.Tabs + 1,
		Size = UDim2.new(0, 0, 1, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 1,
		Font = FONT,
		TextSize = TEXT,
		Text = config.Name or "tab",
		AutoButtonColor = false,
		Theme = { BackgroundColor3 = "Element" },
		Parent = self._tabList,
	}, { padding(0, 12), underline })

	-- Each tab owns a strip of sub-tab buttons and a stack of pages.
	local bar = create("Frame", {
		Position = UDim2.fromOffset(0, 1),
		Size = UDim2.new(1, 0, 1, -2),
		BackgroundTransparency = 1,
		Visible = false,
		Parent = self._subBar,
	}, {
		create("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal,
			SortOrder = Enum.SortOrder.LayoutOrder,
		}),
	})
	local page = create("Frame", {
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Visible = false,
		Parent = self._pages,
	})

	local tab = setmetatable({
		Name = config.Name,
		Instance = page,
		SubTabs = {},
		_window = self,
		_button = button,
		_underline = underline,
		_bar = bar,
		_page = page,
		_active = false,
	}, Tab)
	table.insert(self.Tabs, tab)

	button.MouseButton1Click:Connect(function()
		window:SelectTab(tab)
	end)
	onTheme(function(theme)
		button.TextColor3 = tab._active and theme.Text or theme.SubText
	end)

	if #self.Tabs == 1 then
		self:SelectTab(tab, true)
	end
	return tab
end

-- Docks a panel along the right edge, beside the tab pages (the tabs and sub-tabs
-- narrow to make room). Fill the returned `Container` with whatever you like.
-- config: { Title, Width }
function Window:AddSidePanel(config)
	config = config or {}
	if self._side then
		return self._side
	end
	local width = math.clamp(math.floor(tonumber(config.Width) or 260), 160, 480)
	local top = TITLE_HEIGHT + TAB_HEIGHT
	self._subBar.Size = UDim2.new(1, -width, 0, SUB_HEIGHT)
	self._pages.Size = UDim2.new(1, -width, 1, -(top + SUB_HEIGHT) - STATUS_HEIGHT)

	local icon = sprite(SPRITES.bloomShaded, 2, BLOOM_ROSE)
	icon.AnchorPoint = Vector2.new(0, 0.5)
	icon.Position = UDim2.new(0, 8, 0.5, 0)
	local topLine = create("Frame", {
		Size = UDim2.new(1, 0, 0, 2),
		Theme = { BackgroundColor3 = "Accent" },
	})
	setGlowOn(addGlow(topLine, "element"), true)
	local body = create("Frame", {
		Position = UDim2.fromOffset(0, 28),
		Size = UDim2.new(1, 0, 1, -28),
		BackgroundTransparency = 1,
		ClipsDescendants = true,
	})
	local frame = create("Frame", {
		Name = "SidePanel",
		Position = UDim2.new(1, -width, 0, top),
		Size = UDim2.new(0, width, 1, -top - STATUS_HEIGHT),
		ZIndex = 3,
		Theme = { BackgroundColor3 = "Panel" },
		Parent = self._content,
	}, {
		stroke(),
		topLine,
		create("Frame", {
			Position = UDim2.fromOffset(0, 2),
			Size = UDim2.new(1, 0, 0, 26),
			BackgroundTransparency = 1,
		}, {
			icon,
			label({
				Position = UDim2.fromOffset(30, 0),
				Size = UDim2.new(1, -40, 1, 0),
				Text = config.Title or "panel",
				TextTruncate = Enum.TextTruncate.AtEnd,
				Theme = { TextColor3 = "Accent" },
			}),
		}),
		body,
	})
	glass(frame, "panel")
	self._side = { Container = body, Instance = frame, Width = width }
	return self._side
end

-- Adds a ready-made settings tab: look (theme, glow, glass, petals),
-- configs, toggle key and unload.
function Window:AddSettingsTab(name)
	local window = self
	local tab = self:AddTab(name or "settings")

	-- Look ------------------------------------------------------------
	local look = tab:AddSubTab({ Name = "look", Columns = 2 })

	local themeBox = look:AddLeftGroupbox("theme")
	local themeNames = {}
	for themeName in pairs(Library.Themes) do
		table.insert(themeNames, themeName)
	end
	table.sort(themeNames)
	local accentPicker
	themeBox:AddDropdown({
		Name = "theme",
		Options = themeNames,
		Default = Library.ThemeName,
		Flag = "Sakura.Theme",
		Callback = function(value)
			if value then
				Library._accent = nil
				Library:SetTheme(value)
				if accentPicker then
					accentPicker:Set(Library.Theme.Accent, true)
				end
			end
		end,
	})
	accentPicker = themeBox:AddColorPicker({
		Name = "accent colour",
		Default = Library.Theme.Accent,
		Flag = "Sakura.Accent",
		Callback = function(color)
			Library:SetAccent(color)
		end,
	})
	themeBox:AddToggle({
		Name = "pixel backdrop",
		Default = self._scene.Instance.Visible,
		Flag = "Sakura.Backdrop",
		Callback = function(enabled)
			window:SetBackground(enabled)
		end,
	})

	local petalBox = look:AddLeftGroupbox("petals")
	petalBox:AddToggle({
		Name = "falling petals",
		Default = Library.Petals.Enabled,
		Flag = "Sakura.Petals",
		Callback = function(enabled)
			Library:SetPetals({ Enabled = enabled })
		end,
	})
	petalBox:AddSlider({
		Name = "amount",
		Min = 0,
		Max = 60,
		Default = Library.Petals.Count,
		Flag = "Sakura.PetalCount",
		Callback = function(value)
			Library:SetPetals({ Count = value })
		end,
	})
	petalBox:AddSlider({
		Name = "speed",
		Min = 0.2,
		Max = 3,
		Increment = 0.1,
		Default = Library.Petals.Speed,
		Suffix = "x",
		Flag = "Sakura.PetalSpeed",
		Callback = function(value)
			Library:SetPetals({ Speed = value })
		end,
	})

	local glowBox = look:AddRightGroupbox("glow")
	if not Library.Support.UIShadow then
		glowBox:AddLabel("no UIShadow here: image glow")
	end
	glowBox:AddToggle({
		Name = "glow",
		Default = Library.Glow.Enabled,
		Flag = "Sakura.Glow",
		Callback = function(enabled)
			Library:SetGlow({ Enabled = enabled })
		end,
	})
	glowBox:AddSlider({
		Name = "size",
		Min = 0,
		Max = 96,
		Default = Library.Glow.Size,
		Suffix = "px",
		Flag = "Sakura.GlowSize",
		Callback = function(value)
			Library:SetGlow({ Size = value })
		end,
	})
	glowBox:AddSlider({
		Name = "spread",
		Min = 0,
		Max = 16,
		Default = Library.Glow.Spread,
		Suffix = "px",
		Flag = "Sakura.GlowSpread",
		Callback = function(value)
			Library:SetGlow({ Spread = value })
		end,
	})
	glowBox:AddSlider({
		Name = "strength",
		Min = 0,
		Max = 100,
		Default = math.floor(Library.Glow.Strength * 100 + 0.5),
		Suffix = "%",
		Flag = "Sakura.GlowStrength",
		Callback = function(value)
			Library:SetGlow({ Strength = value / 100 })
		end,
	})
	glowBox:AddSlider({
		Name = "control glow",
		Min = 0,
		Max = 100,
		Default = math.floor(Library.Glow.ElementStrength * 100 + 0.5),
		Suffix = "%",
		Flag = "Sakura.GlowControls",
		Callback = function(value)
			Library:SetGlow({ ElementStrength = value / 100 })
		end,
	})
	glowBox:AddToggle({
		Name = "pulse",
		Default = Library.Glow.Pulse,
		Flag = "Sakura.GlowPulse",
		Callback = function(enabled)
			Library:SetGlow({ Pulse = enabled })
		end,
	})
	glowBox:AddToggle({
		Name = "glow on controls",
		Default = Library.Glow.Elements,
		Flag = "Sakura.GlowElements",
		Callback = function(enabled)
			Library:SetGlow({ Elements = enabled })
		end,
	})
	local glowPicker
	glowBox:AddToggle({
		Name = "use accent colour",
		Default = Library.Glow.Color == nil,
		Flag = "Sakura.GlowAccent",
		Callback = function(enabled)
			Library:SetGlow({ Color = enabled and false or (glowPicker and glowPicker.Value or Library.Theme.Accent) })
		end,
	})
	glowPicker = glowBox:AddColorPicker({
		Name = "glow colour",
		Default = Library.Glow.Color or Library.Theme.Accent,
		Flag = "Sakura.GlowColor",
		Callback = function(color)
			if Library.Flags["Sakura.GlowAccent"] == false then
				Library:SetGlow({ Color = color })
			end
		end,
	})

	local glassBox = look:AddRightGroupbox("glass")
	if not Library.Support.UIBlur then
		glassBox:AddLabel("no UIBlur here: tint only")
	end
	glassBox:AddDropdown({
		Name = "blur",
		Options = { "Off", "Light", "Medium", "Heavy" },
		Default = Library.Glass.Blur,
		Flag = "Sakura.Blur",
		Callback = function(value)
			if value then
				Library:SetGlass({ Blur = value })
			end
		end,
	})
	glassBox:AddSlider({
		Name = "panel opacity",
		Min = 5,
		Max = 100,
		Default = math.floor((1 - Library.Glass.Transparency) * 100 + 0.5),
		Suffix = "%",
		Flag = "Sakura.Opacity",
		Callback = function(value)
			Library:SetGlass({ Transparency = 1 - value / 100 })
		end,
	})

	-- Configs ---------------------------------------------------------
	local data = tab:AddSubTab({ Name = "configs", Columns = 2 })
	local configs = data:AddLeftGroupbox("configs")
	local nameBox = configs:AddTextbox({ Name = "config name", Default = "default" })
	local picker = configs:AddDropdown({ Name = "saved configs", Options = Library:ListConfigs(self.ConfigFolder) })
	picker:OnChanged(function(value)
		if value then
			nameBox:Set(value, true)
		end
	end)
	configs:AddButton({
		Name = "save config",
		Callback = function()
			local ok, err = Library:SaveConfig(nameBox.Value, window.ConfigFolder)
			Library:Notify({
				Title = "configs",
				Content = ok and ("saved '" .. nameBox.Value .. "'") or ("save failed: " .. tostring(err)),
			})
			picker:Refresh(Library:ListConfigs(window.ConfigFolder))
		end,
	})
	configs:AddButton({
		Name = "load config",
		Callback = function()
			local ok, err = Library:LoadConfig(nameBox.Value, window.ConfigFolder)
			Library:Notify({
				Title = "configs",
				Content = ok and ("loaded '" .. nameBox.Value .. "'") or ("load failed: " .. tostring(err)),
			})
		end,
	})

	local session = data:AddRightGroupbox("session")
	session:AddKeybind({
		Name = "toggle ui",
		Default = self.ToggleKey,
		Flag = "Sakura.ToggleKey",
		ChangedCallback = function(key)
			window:SetToggleKey(key)
		end,
	})
	session:AddButton({
		Name = "unload ui",
		Callback = function()
			Library:Unload()
		end,
	})
	return tab
end

---------------------------------------------------------------------
-- Configs
---------------------------------------------------------------------

local function hasFileApi()
	return type(writefile) == "function"
		and type(readfile) == "function"
		and type(isfile) == "function"
		and type(makefolder) == "function"
end

local function configPath(name, folder)
	return (folder or "SakuraUI") .. "/" .. string.gsub(tostring(name), "[^%w%-_ ]", "") .. ".json"
end

function Library:SaveConfig(name, folder)
	if not hasFileApi() then
		return false, "executor has no file API"
	end
	local data = {}
	for flag, option in pairs(self.Options) do
		if option.Type == "ColorPicker" then
			data[flag] = colorToHex(option.Value)
		else
			data[flag] = option.Value
		end
	end
	return pcall(function()
		folder = folder or "SakuraUI"
		if not (isfolder and isfolder(folder)) then
			makefolder(folder)
		end
		writefile(configPath(name, folder), HttpService:JSONEncode(data))
	end)
end

function Library:LoadConfig(name, folder)
	if not hasFileApi() then
		return false, "executor has no file API"
	end
	local path = configPath(name, folder)
	if not isfile(path) then
		return false, "config not found"
	end
	local ok, data = pcall(function()
		return HttpService:JSONDecode(readfile(path))
	end)
	if not ok or type(data) ~= "table" then
		return false, "config is corrupt"
	end
	for flag, value in pairs(data) do
		local option = self.Options[flag]
		if option then
			-- Not silent: callbacks must run so the loaded state takes effect.
			option:Set(value)
		end
	end
	return true
end

function Library:ListConfigs(folder)
	local names = {}
	folder = folder or "SakuraUI"
	if type(listfiles) ~= "function" or type(isfolder) ~= "function" or not isfolder(folder) then
		return names
	end
	local ok, files = pcall(listfiles, folder)
	if not ok then
		return names
	end
	for _, path in ipairs(files) do
		local name = string.match(tostring(path), "([^/\\]+)%.json$")
		if name then
			table.insert(names, name)
		end
	end
	table.sort(names)
	return names
end

---------------------------------------------------------------------
-- Teardown
---------------------------------------------------------------------

function Library:Unload()
	if self.Unloaded then
		return
	end
	self.Unloaded = true
	for _, conn in ipairs(self._connections) do
		conn:Disconnect()
	end
	self._connections = {}
	self._bindings = {}
	self._themeCallbacks = {}
	self._windows = {}
	glows = {}
	glasses = {}
	for key, gui in pairs(self._guis) do
		gui:Destroy()
		self._guis[key] = nil
	end
	notifyHolder = nil
	toasts = {}
	watermark = nil
	safeCall(self.OnUnload)
end

return Library
end)()

-- Images: the frekksec.lua logo (embedded, split into a white text layer and a white
-- glow layer so the glow can be recoloured) and the baked-blur "frost" backdrops that
-- stand in for UIBlur. Both need writefile + getcustomasset; without them the window
-- falls back to a text title and tinted panels.
local loadFrekksecAssets
do
    local LOGO_TEXT = ""
    local LOGO_GLOW = ""
    local FROST_URL = "https://raw.githubusercontent.com/282882yea/e/claude/executor-ui-tabs-pixeled-aww4ux/frekksec/assets/"
    local FOLDER = "frekksec/assets"
    local VERSION = "v1"

    local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local function decode(text)
        local value = {}
        for i = 1, 64 do value[string.byte(B64, i)] = i - 1 end
        local out, chunk = {}, {}
        local bits, count = 0, 0
        for i = 1, #text do
            local v = value[string.byte(text, i)]
            if v then
                bits = bits * 64 + v
                count = count + 6
                if count >= 8 then
                    count = count - 8
                    local p = 2 ^ count
                    local byte = math.floor(bits / p)
                    bits = bits - byte * p
                    chunk[#chunk + 1] = string.char(byte)
                    if #chunk >= 4096 then
                        out[#out + 1] = table.concat(chunk)
                        chunk = {}
                    end
                end
            end
        end
        out[#out + 1] = table.concat(chunk)
        return table.concat(out)
    end

    function loadFrekksecAssets()
        local function fn(value) return type(value) == "function" and value or nil end
        local writefile, isfile, makefolder, isfolder = fn(writefile), fn(isfile), fn(makefolder), fn(isfolder)
        local asset = fn(getcustomasset) or fn(getsynasset)
        local assets = {}
        if not (writefile and asset) then return assets end
        pcall(function()
            if makefolder and not (isfolder and isfolder("frekksec")) then makefolder("frekksec") end
            if makefolder and not (isfolder and isfolder(FOLDER)) then makefolder(FOLDER) end
        end)
        local function save(name, data)
            local path = FOLDER .. "/" .. name
            local ok, id = pcall(function()
                if not (isfile and isfile(path)) then writefile(path, data) end
                return asset(path)
            end)
            return ok and type(id) == "string" and id ~= "" and id or nil
        end

        local text = save("logo-text-" .. VERSION .. ".png", decode(LOGO_TEXT))
        local glow = save("logo-glow-" .. VERSION .. ".png", decode(LOGO_GLOW))
        if text and glow then
            assets.Logo = {Image = text, Glow = glow, Width = 448, Height = 110}
        end

        -- Frost images are fetched once in the background, then read from the cache.
        assets.Frost = {Width = 1006, Height = 586, ImageWidth = 252, ImageHeight = 147, Images = {}}
        function assets:FetchFrost(onReady)
            task.spawn(function()
                for _, scene in ipairs({"Dusk", "Night", "Day"}) do
                    local set = {}
                    for _, level in ipairs({"Light", "Medium", "Heavy"}) do
                        local file = ("frost-%s-%s.png"):format(scene:lower(), level:lower())
                        local path = FOLDER .. "/" .. VERSION .. "-" .. file
                        local cached = isfile and pcall(isfile, path) and isfile(path)
                        if not cached then
                            local ok, body = pcall(function() return game:HttpGet(FROST_URL .. file) end)
                            if ok and type(body) == "string" and body:sub(2, 4) == "PNG" then
                                pcall(writefile, path, body)
                                cached = true
                            end
                        end
                        if cached then
                            local ok, id = pcall(asset, path)
                            if ok and type(id) == "string" and id ~= "" then set[level] = id end
                        end
                    end
                    self.Frost.Images[scene] = set
                    if onReady then onReady() end
                end
            end)
        end
        return assets
    end
end

-- UI layer: the calls frekksec makes (window, tabs, groupboxes, controls, toasts and the
-- live preview) implemented on top of the Sakura UI library bundled above.
local function loadFrekksecUI(private)
    local UIS = game:GetService("UserInputService")
    local RunService = game:GetService("RunService")
    local black = Color3.new(0, 0, 0)
    local ui = {
        Registry = setmetatable({}, {__mode = "k"}),
        -- Theme colours. The settings tab edits these, then calls UpdateColorsUsingRegistry.
        MainColor = Color3.fromRGB(54, 30, 72),
        AccentColor = Color3.fromRGB(255, 126, 182),
        BackgroundColor = Color3.fromRGB(35, 19, 48),
        OutlineColor = Color3.fromRGB(104, 66, 128),
        FontColor = Color3.fromRGB(255, 236, 245),
        SurfaceGlowColor = Color3.fromRGB(255, 126, 182),
        ControlGlowColor = Color3.fromRGB(255, 126, 182),
        LogoGlowColor = Color3.fromRGB(180, 124, 255),
        Scene = "Dusk",
        Library = Sakura,
        _connections = {},
        _shadows = setmetatable({}, {__mode = "k"}),
        _glowStrength = 0.35,
    }
    private.Toggles, private.Options = {}, {}

    local GUI = {Frame = true, TextLabel = true, TextButton = true, TextBox = true, ScrollingFrame = true, ImageLabel = true}
    local function create(class, properties)
        local object = Instance.new(class)
        if GUI[class] then object.BorderSizePixel = 0 end
        for key, value in pairs(properties) do
            if key ~= "Parent" then object[key] = value end
        end
        object.Parent = properties.Parent
        return object
    end
    -- Colours derived from the five theme colours. Light themes get pale bars instead of dark ones.
    local function derive()
        local bg, accent, font = ui.BackgroundColor, ui.AccentColor, ui.FontColor
        ui.Bright = 0.299 * bg.R + 0.587 * bg.G + 0.114 * bg.B > 0.55
        ui.StageColor = ui.Bright and bg:Lerp(accent, 0.12) or bg:Lerp(black, 0.5)
        ui.GridColor = ui.OutlineColor:Lerp(bg, 0.5)
        ui.SubColor = font:Lerp(bg, 0.4)
        ui.HeaderColor = ui.Bright and bg:Lerp(accent, 0.16) or bg:Lerp(black, 0.3)
        ui.FrameColor = ui.Bright and font:Lerp(accent, 0.25) or bg:Lerp(black, 0.55)
    end
    derive()

    function ui:Create(class, props) return create(class, props) end
    function ui:CreateLabel(props)
        props.Font = props.Font or Enum.Font.Arcade
        props.TextSize = props.TextSize or 8
        props.TextXAlignment = props.TextXAlignment or Enum.TextXAlignment.Left
        if props.BackgroundTransparency == nil then props.BackgroundTransparency = 1 end
        props.TextColor3 = props.TextColor3 or self.FontColor
        return create("TextLabel", props)
    end
    function ui:AddToRegistry(object, props) self.Registry[object] = props end
    function ui:GetDarkerColor(color) return color:Lerp(black, 0.35) end
    function ui:_watch(signal, callback)
        local connection = signal:Connect(callback)
        table.insert(self._connections, connection)
        return connection
    end

    -- Extra UIShadows (HUD, keybind list...) follow the window glow settings.
    function ui:_paintShadows()
        for shadow in pairs(self._shadows) do
            if shadow.Parent then
                shadow.Color = self.SurfaceGlowColor
                shadow.Transparency = 1 - math.clamp(self._glowStrength * 1.4, 0, 1)
            end
        end
    end
    function ui:SurfaceShadow(parent, blur)
        if not Sakura.Support.UIShadow then return nil end
        local made, shadow = pcall(function()
            local item = Instance.new("UIShadow")
            item.BlurRadius = UDim.new(0, blur or 12)
            item.Parent = parent
            return item
        end)
        if not made then return nil end
        self._shadows[shadow] = true
        self:_paintShadows()
        return shadow
    end
    -- Border lights up under the pointer.
    function ui:AttachButtonGlow(button)
        local border = button:FindFirstChildOfClass("UIStroke")
        if not border then return end
        button.MouseEnter:Connect(function() border.Color = self.AccentColor end)
        button.MouseLeave:Connect(function() border.Color = self.OutlineColor end)
    end

    -- Maps the five theme colours onto a Sakura theme and recolours everything registered.
    function ui:UpdateColorsUsingRegistry()
        derive()
        local accent, bg, main, line, font = self.AccentColor, self.BackgroundColor, self.MainColor, self.OutlineColor, self.FontColor
        Sakura:SetTheme({
            Scene = self.Scene,
            Outline = self.FrameColor,
            Accent = accent,
            Panel = bg,
            Header = self.HeaderColor,
            Element = main,
            ElementHover = main:Lerp(font, 0.1),
            Stroke = line,
            Text = font,
            SubText = self.SubColor,
            Knob = self.Bright and accent:Lerp(black, 0.35) or Color3.new(1, 1, 1),
        })
        Sakura:SetGlow({SurfaceColor = self.SurfaceGlowColor, ControlColor = self.ControlGlowColor, LogoColor = self.LogoGlowColor})
        for object, properties in pairs(self.Registry) do
            if object.Parent then
                for property, key in pairs(properties) do object[property] = self[key] end
            end
        end
        self:_paintShadows()
    end

    -- Look settings --------------------------------------------------------
    function ui:SetMenuOpacity(_, percent) Sakura:SetGlass({Transparency = 1 - percent / 100}) end
    function ui:SetPanelBlur(level) Sakura:SetGlass({Blur = level}) end
    function ui:SetButtonGlow(strength, controls) Sakura:SetGlow({ElementStrength = strength, Elements = controls ~= false}) end
    function ui:SetWindowGlow(strength, width)
        self._glowStrength = strength
        Sakura:SetGlow({Strength = strength, Size = width})
        self:_paintShadows()
    end
    function ui:SetLogoGlow(percent) Sakura:SetGlow({LogoStrength = math.clamp((tonumber(percent) or 85) / 100, 0, 1)}) end
    -- Frost (baked blur) is skipped while a custom background image covers the scene.
    function ui:SetFrost(on) Sakura:SetFrost({Enabled = on ~= false}) end
    function ui:SetGlowPulse(on) Sakura:SetGlow({Pulse = on == true}) end
    function ui:SetScene(name)
        if self.Scene ~= name then self.Scene = name; self:UpdateColorsUsingRegistry() end
    end
    function ui:SetBackdrop(on) if self.Window then self.Window:SetBackground(on) end end
    function ui:SetPetals(on, count) Sakura:SetPetals({Enabled = on == true, Count = count}) end
    function ui:SetScale(percent) if self.Window then self.Window:SetScale(percent) end end
    function ui:SetToggleKey(key) if self.Window then self.Window:SetToggleKey(key) end end
    function ui:CaptureKeys(active)
        if active then Sakura:CaptureKeys(true)
        else task.defer(function() Sakura:CaptureKeys(false) end) end -- let both key handlers see this press
    end
    function ui:SetOpen(value) if self.Window then self.Window:SetVisible(value) end end
    function ui:IsOpen() return self.Window ~= nil and self.Window.Visible end
    function ui:SetNotificationSide(side) Sakura:SetNotifications({Side = side}) end
    function ui:Notify(text, duration) Sakura:Notify({Title = "frekksec", Content = tostring(text), Duration = duration or 4}) end
    function ui:SetWatermarkVisibility(value) self.Mark:SetVisible(value) end
    function ui:SetWatermark(text) self.Mark:SetFields(string.split(text, " | ")) end
    function ui:Mount() end
    function ui:Unload()
        if self._unloaded then return end
        self._unloaded = true
        for _, connection in ipairs(self._connections) do pcall(connection.Disconnect, connection) end
        table.clear(self._connections)
        Sakura:Unload()
    end

    function ui:MakeDraggable(object, keepOnScreen)
        local pointer, origin, start
        object.Active = true
        object.InputBegan:Connect(function(input)
            local kind = input.UserInputType
            if not pointer and (kind == Enum.UserInputType.MouseButton1 or kind == Enum.UserInputType.Touch) then
                pointer, origin, start = input, object.Position, input.Position
            end
        end)
        self:_watch(UIS.InputChanged, function(input)
            if pointer and (input == pointer or (pointer.UserInputType == Enum.UserInputType.MouseButton1
                and input.UserInputType == Enum.UserInputType.MouseMovement)) then
                local delta = input.Position - start
                if keepOnScreen then
                    local screen, size, anchor = self.ScreenGui.AbsoluteSize, object.AbsoluteSize, object.AnchorPoint
                    local minX, minY = size.X * anchor.X, size.Y * anchor.Y
                    local x = math.clamp(screen.X * origin.X.Scale + origin.X.Offset + delta.X,
                        minX, math.max(minX, screen.X - size.X + minX))
                    local y = math.clamp(screen.Y * origin.Y.Scale + origin.Y.Offset + delta.Y,
                        minY, math.max(minY, screen.Y - size.Y + minY))
                    object.Position = UDim2.new(origin.X.Scale, x - screen.X * origin.X.Scale,
                        origin.Y.Scale, y - screen.Y * origin.Y.Scale)
                else
                    object.Position = origin + UDim2.fromOffset(delta.X, delta.Y)
                end
            end
        end)
        self:_watch(UIS.InputEnded, function(input)
            if input == pointer or input.UserInputType == Enum.UserInputType.MouseButton1 then pointer = nil end
        end)
    end

    -- Controls --------------------------------------------------------------
    local function option(registry, id, initial, render)
        local item = {Value = initial, listeners = {}}
        function item:OnChanged(fn) table.insert(self.listeners, fn) end
        function item:SetValue(value, fromControl)
            local changed = self.Value ~= value
            self.Value = value
            if not fromControl then render(value) end
            if changed then
                for _, listener in ipairs(self.listeners) do listener(value) end
            end
        end
        registry[id] = item
        return item
    end
    local function group(box)
        local g = {Container = box.Container, Box = box}
        function g:Resize() end
        function g:AddButton(text, fn)
            local control = box:AddButton({Name = text, Callback = fn})
            return {SetText = function(_, value) control:SetName(value) end}
        end
        function g:AddLabel(text)
            local label = box:AddLabel(text)
            local line = label.TextLabel
            if #tostring(text) > 36 then label:SetWrapped(true) end -- long hints wrap instead of being cut off
            -- Callers switch TextWrapped on for long text; make the row grow with it.
            line:GetPropertyChangedSignal("TextWrapped"):Connect(function()
                if line.TextWrapped and line.AutomaticSize == Enum.AutomaticSize.None then label:SetWrapped(true) end
            end)
            return {
                TextLabel = line,
                AddColorPicker = function(_, id, info)
                    label.Instance.Visible = false
                    local item
                    local picker = box:AddColorPicker({Name = text, Default = info.Default, Callback = function(value)
                        if item then item:SetValue(value, true) end
                    end})
                    item = option(private.Options, id, info.Default, function(value) picker:Set(value, true) end)
                    item.SetValueRGB = item.SetValue
                    return item
                end,
            }
        end
        function g:AddToggle(id, info)
            local item
            local control = box:AddToggle({Name = info.Text, Default = false, Callback = function(value)
                if item then item:SetValue(value, true) end
            end})
            control:Set(info.Default == true, true)
            item = option(private.Toggles, id, info.Default, function(value) control:Set(value, true) end)
            return item
        end
        function g:AddSlider(id, info)
            local item
            local wide = info.ToFraction ~= nil
            local function toSlider(value) return wide and info.ToFraction(value) * 1000 or value end
            local control = box:AddSlider({
                Name = info.Text, Min = wide and 0 or info.Min, Max = wide and 1000 or info.Max,
                Default = toSlider(info.Default), Increment = wide and 1 or 10 ^ -(info.Rounding or 0),
                Format = wide and function(value) return info.Format(info.FromFraction(value / 1000)) end or nil,
                Callback = function(value)
                    if item then item:SetValue(wide and info.FromFraction(value / 1000) or value, true) end
                end,
            })
            item = option(private.Options, id, info.Default, function(value) control:Set(toSlider(value), true) end)
            return item
        end
        function g:AddInput(id, info)
            local item
            local initial = tostring(info.Default or "")
            local control = box:AddTextbox({Name = info.Text, Default = initial, Callback = function(value)
                if item then item:SetValue(value, true) end
            end})
            item = option(private.Options, id, initial, function(value) control:Set(tostring(value or ""), true) end)
            return item
        end
        function g:AddDropdown(id, info)
            local item
            local default = info.Default
            if not info.AllowNull and not table.find(info.Values, default) then default = info.Values[1] end
            local control = box:AddDropdown({Name = info.Text, Options = info.Values, Default = default, Callback = function(value)
                if item then item:SetValue(value, true) end
            end})
            item = option(private.Options, id, control.Value, function(value) control:Set(value, true) end)
            item.Values = info.Values
            function item:SetValues() control:Refresh(self.Values) end
            return item
        end
        return g
    end
    local function tabbox(box)
        return {AddTab = function(_, name) return group(box:AddTab(name)) end}
    end
    local function surface(host)
        return {
            AddLeftGroupbox = function(_, title) return group(host:AddLeftGroupbox(title)) end,
            AddRightGroupbox = function(_, title) return group(host:AddRightGroupbox(title)) end,
            AddLeftTabbox = function() return tabbox(host:AddLeftTabbox()) end,
            AddRightTabbox = function() return tabbox(host:AddRightTabbox()) end,
        }
    end

    -- Live preview ----------------------------------------------------------
    -- A neutral robot that mirrors the movement mode frekksec reports. It never drives
    -- the game or claims a replicated server position.
    local function buildStatus(window)
        local side = window:AddSidePanel({Title = "live preview", Width = 250})
        local pane = side.Container
        local STAGE_W, STAGE_H = side.Width - 16, 168
        local stage = create("Frame", {
            Name = "FrekksecMovementVisual", Parent = pane, Position = UDim2.fromOffset(8, 8),
            Size = UDim2.fromOffset(STAGE_W, STAGE_H), BackgroundColor3 = ui.StageColor, ClipsDescendants = true,
        })
        ui:AddToRegistry(stage, {BackgroundColor3 = "StageColor"})
        local edge = create("UIStroke", {Parent = stage, ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Thickness = 1, Color = ui.OutlineColor})
        ui:AddToRegistry(edge, {Color = "OutlineColor"})
        local function gridLine(size, position)
            local item = create("Frame", {Parent = stage, Size = size, Position = position, BackgroundColor3 = ui.GridColor})
            ui:AddToRegistry(item, {BackgroundColor3 = "GridColor"})
        end
        for i = 1, 3 do gridLine(UDim2.new(1, -10, 0, 1), UDim2.new(0, 5, i / 4, 0)) end
        for i = 1, 5 do gridLine(UDim2.new(0, 1, 1, -38), UDim2.new(i / 6, 0, 0, 23)) end
        local modeText = ui:CreateLabel({Parent = stage, Text = "ROBOT / IDLE", Position = UDim2.fromOffset(8, 7),
            Size = UDim2.new(1, -16, 0, 10), ZIndex = 12, TextColor3 = ui.AccentColor})
        ui:AddToRegistry(modeText, {TextColor3 = "AccentColor"})
        local foot = ui:CreateLabel({Parent = stage, Text = "LIVE / MOVEMENT PREVIEW", Position = UDim2.new(0, 8, 1, -16),
            Size = UDim2.new(1, -16, 0, 10), ZIndex = 12, TextTruncate = Enum.TextTruncate.AtEnd, TextColor3 = ui.SubColor})
        ui:AddToRegistry(foot, {TextColor3 = "SubColor"})

        local ring = create("Frame", {Parent = stage, Size = UDim2.fromOffset(86, 86), Position = UDim2.fromScale(0.5, 0.56),
            AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = 1})
        local ringStroke = create("UIStroke", {Parent = ring, ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
            Thickness = 1, Transparency = 0.35, Color = ui.AccentColor})
        ui:AddToRegistry(ringStroke, {Color = "AccentColor"})

        local limbs = {}
        local function figure(role)
            local avatar = create("Frame", {
                Name = "StatusRobot_" .. role, Parent = stage, BackgroundTransparency = 1,
                Size = UDim2.fromOffset(48, 82), Position = UDim2.fromScale(0.5, 0.55),
                AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = role == "mover" and 8 or 6,
            })
            local alpha = role == "ghost" and 0.62 or (role == "target" and 0.42 or 0)
            local body = role == "target" and Color3.fromRGB(150, 140, 175) or ui.AccentColor
            local function block(name, x, y, w, h, fill, accent)
                local part = create("Frame", {
                    Name = name, Parent = avatar, Size = UDim2.fromScale(w, h), Position = UDim2.fromScale(x, y),
                    AnchorPoint = Vector2.new(0.5, 0), BackgroundColor3 = fill,
                    BackgroundTransparency = alpha, ZIndex = avatar.ZIndex,
                })
                if accent and role ~= "target" then ui:AddToRegistry(part, {BackgroundColor3 = "AccentColor"}) end
                return part
            end
            block("Antenna", 0.5, 0.015, 0.07, 0.09, body, true)
            block("Head", 0.5, 0.09, 0.62, 0.25, Color3.fromRGB(255, 238, 246))
            block("LeftEye", 0.37, 0.17, 0.075, 0.055, Color3.fromRGB(58, 30, 78))
            block("RightEye", 0.63, 0.17, 0.075, 0.055, Color3.fromRGB(58, 30, 78))
            block("Smile", 0.5, 0.263, 0.20, 0.025, Color3.fromRGB(58, 30, 78))
            block("Torso", 0.5, 0.37, 0.48, 0.29, body, true)
            block("Badge", 0.5, 0.45, 0.16, 0.07, Color3.fromRGB(255, 255, 255))
            limbs[avatar] = {
                block("LeftArm", 0.17, 0.38, 0.14, 0.30, body, true),
                block("RightArm", 0.83, 0.38, 0.14, 0.30, body, true),
                block("LeftLeg", 0.35, 0.68, 0.19, 0.28, Color3.fromRGB(205, 170, 225)),
                block("RightLeg", 0.65, 0.68, 0.19, 0.28, Color3.fromRGB(205, 170, 225)),
            }
            return avatar
        end
        local target, ghost, mover = figure("target"), figure("ghost"), figure("mover")
        local function poseFigure(avatar, pose, t)
            local parts = limbs[avatar]
            local swing = math.sin(t * 12)
            if pose == "split" then
                parts[1].Rotation, parts[2].Rotation = 58, -58
                parts[3].Rotation, parts[4].Rotation = 64, -64
            elseif pose == "run" then
                parts[1].Rotation, parts[2].Rotation = swing * 48, -swing * 48
                parts[3].Rotation, parts[4].Rotation = -swing * 37, swing * 37
            else
                parts[1].Rotation, parts[2].Rotation = 5 + math.sin(t * 2) * 3, -5 - math.sin(t * 2) * 3
                parts[3].Rotation, parts[4].Rotation = 0, 0
            end
        end
        local trails, streaks = {}, {}
        for i = 1, 5 do
            local dot = create("Frame", {Parent = stage, Size = UDim2.fromOffset(4, 4), AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = ui.AccentColor, BackgroundTransparency = 0.18 + i * 0.15})
            ui:AddToRegistry(dot, {BackgroundColor3 = "AccentColor"})
            trails[i] = dot
        end
        for i = 1, 4 do
            local beam = create("Frame", {Parent = stage, Size = UDim2.new(0.34, 0, 0, 1), Position = UDim2.new(0.33, 0, 0.36 + i * 0.09, 0),
                BackgroundColor3 = ui.AccentColor, BackgroundTransparency = 0.28 + i * 0.13})
            ui:AddToRegistry(beam, {BackgroundColor3 = "AccentColor"})
            streaks[i] = beam
        end

        -- Status rows under the stage: accent key on the left, wrapped value on the right.
        local rowTop = 8 + STAGE_H + 8
        local rows = create("ScrollingFrame", {
            Parent = pane, Position = UDim2.fromOffset(8, rowTop), Size = UDim2.new(1, -16, 1, -rowTop - 6),
            BackgroundTransparency = 1, ScrollBarThickness = 2, CanvasSize = UDim2.new(),
            AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollingDirection = Enum.ScrollingDirection.Y,
            ScrollBarImageColor3 = ui.AccentColor,
        })
        ui:AddToRegistry(rows, {ScrollBarImageColor3 = "AccentColor"})
        create("UIListLayout", {Parent = rows, SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 5)})
        create("UIPadding", {Parent = rows, PaddingRight = UDim.new(0, 6)})
        local entries, order, status = {}, 0, {Mode = "Idle", GhostHeight = 0}
        function status:Set(key, value)
            local entry = entries[key]
            if not entry then
                order += 1
                local row = create("Frame", {Parent = rows, LayoutOrder = order, Size = UDim2.new(1, 0, 0, 19),
                    AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1})
                create("UIListLayout", {Parent = row, SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 3)})
                local name = ui:CreateLabel({Parent = row, LayoutOrder = 1, Size = UDim2.new(1, 0, 0, 8), Text = key,
                    TextTruncate = Enum.TextTruncate.AtEnd, TextColor3 = ui.AccentColor})
                ui:AddToRegistry(name, {TextColor3 = "AccentColor"})
                entry = ui:CreateLabel({Parent = row, LayoutOrder = 2, Size = UDim2.new(1, 0, 0, 8),
                    AutomaticSize = Enum.AutomaticSize.Y, TextWrapped = true, TextYAlignment = Enum.TextYAlignment.Top,
                    LineHeight = 1.3, Text = ""})
                ui:AddToRegistry(entry, {TextColor3 = "FontColor"})
                entries[key] = entry
            end
            local text = tostring(value)
            if entry.Text ~= text then entry.Text = text end
        end
        function status:SetGhostHeight(value)
            if type(value) == "number" and value == value and value >= 0 and value <= 1e37 then self.GhostHeight = value end
        end
        function status:SetAnimation(mode)
            if type(mode) ~= "string" or mode == "" then mode = "Idle" end
            if self.Mode == mode then return end
            self.Mode, modeText.Text = mode, "ROBOT / " .. string.upper(mode)
        end
        local captions = {
            ["Void TP"] = "TELEPORT / ROBOT RUN", ["Void Hide"] = "VOID / SIDE TO SIDE",
            Orbit = "ORBIT / TRACKED TARGET", Strafe = "STRAFE / SIDE TO SIDE", Jitter = "JITTER / RANDOM OFFSETS",
            ["Random sphere"] = "SPHERE / 3D PATH", Sphere = "SPHERE / 3D PATH", ["Lunar Riot"] = "LUNAR / ROTATION",
            Paused = "PAUSED / NO ACTIVE MOVEMENT",
        }
        -- Positions snap to a 2px grid so the robot moves like pixel art.
        local function snap(value) return math.floor(value / 2 + 0.5) * 2 end
        local function at(x, y) return UDim2.fromOffset(snap(x * STAGE_W), snap(y * STAGE_H)) end
        local clock, accumulated = 0, 0
        ui:_watch(RunService.Heartbeat, function(dt)
            if ui._unloaded or not window.Visible or window.Minimized or not stage.Parent then return end
            if type(dt) ~= "number" or dt ~= dt or dt <= 0 then return end
            accumulated += math.min(dt, 0.1)
            if accumulated < 1 / 30 then return end
            clock += math.min(accumulated, 0.08)
            accumulated = 0
            local mode, t = status.Mode, clock
            if mode == "Hybrid" then mode = math.floor(t / 2.5) % 2 == 0 and "Orbit" or "Void TP" end
            local active = mode ~= "Paused" and mode ~= "Idle"
            local x, y, size, rotation = 0.5, 0.55, 1, 0
            local pose = mode == "Orbit" and "split" or ((mode == "Void TP" or mode == "Void Hide" or mode == "Strafe") and "run" or "idle")
            local streakOn = mode == "Void TP" or mode == "Void Hide" or mode == "Jitter"
            if mode == "Jitter" then
                local step = math.floor(t * 14)
                x, y = 0.5 + 0.23 * math.sin(step * 6.7), 0.55 + 0.16 * math.cos(step * 4.3)
            elseif mode == "Strafe" then x, rotation = 0.5 + 0.30 * math.sin(t * 3), 10 * math.sin(t * 3)
            elseif mode == "Random sphere" or mode == "Sphere" then
                x, y, size = 0.5 + 0.27 * math.cos(t * 2.1), 0.56 + 0.25 * math.sin(t * 3.1), 0.8 + 0.15 * math.sin(t * 2.1)
            elseif mode == "Fake Position" then x, y = 0.5 + 0.14 * math.sin(t * 1.6), 0.64
            elseif mode == "Lunar Riot" then x, rotation = 0.5 + 0.16 * math.sin(t * 3), (t * 220) % 360
            else y = 0.55 + math.sin(t * 2) * 0.015 end
            local stageH, stageW = STAGE_H, STAGE_W
            local availableH = math.max(18, stageH - 45)
            local figureHeight = math.max(12, math.min(availableH * 0.90, 90) * size)
            local figureWidth = math.max(8, math.min(figureHeight * (pose == "split" and 1.02 or 0.62), stageW * 0.55))
            local leftRightRoom = math.max(0, 0.5 - (figureWidth / 2 + 7) / stageW)
            local minY, maxY = (22 + figureHeight / 2) / stageH, (stageH - 18 - figureHeight / 2) / stageH
            local centerY, roomY = (minY + maxY) * 0.5, math.max(0, (maxY - minY) * 0.45)
            if mode == "Orbit" then
                x, y = 0.5 + leftRightRoom * 0.84 * math.cos(t * 2.4), centerY + roomY * 0.9 * math.sin(t * 2.4)
            elseif mode == "Void Hide" then x, y = 0.5 + leftRightRoom * 0.92 * math.sin(t * 3.8), centerY
            elseif mode == "Void TP" then x, y = 0.5 + ((t * 2.8) % 2 < 1 and -1 or 1) * leftRightRoom * 0.88, centerY end
            x, y = math.clamp(x, 0.5 - leftRightRoom, 0.5 + leftRightRoom), math.clamp(y, math.min(minY, maxY), math.max(minY, maxY))
            mover.Position, mover.Size, mover.Rotation = at(x, y), UDim2.fromOffset(snap(figureWidth), snap(figureHeight)), rotation
            local ghostHeight = figureHeight * 0.72
            ghost.Size = UDim2.fromOffset(snap(figureWidth * 0.72), snap(ghostHeight))
            target.Size, target.Position = UDim2.fromOffset(snap(figureWidth * 0.62), snap(figureHeight * 0.62)), at(0.5, centerY)
            target.Visible = active and mode ~= "Fake Position" and mode ~= "Lunar Riot"
            ghost.Visible = mode == "Fake Position" or mode == "Void TP" or mode == "Jitter"
            local ghostY = y
            if mode == "Fake Position" then
                local lift = 0.12 + 0.20 * math.log10(1 + status.GhostHeight) / 37
                local minGhostY = (22 + ghostHeight / 2) / stageH
                local maxGhostY = (stageH - 18 - ghostHeight / 2) / stageH
                ghostY = math.clamp(y - lift, math.min(minGhostY, maxGhostY), math.max(minGhostY, maxGhostY))
            end
            ghost.Position = at(mode == "Fake Position" and x or (x < 0.5 and 0.79 or 0.21), ghostY)
            poseFigure(mover, pose, t)
            poseFigure(ghost, pose, t - 0.12)
            poseFigure(target, "idle", t)
            ring.Visible = mode == "Orbit" or mode == "Random sphere" or mode == "Sphere" or mode == "Lunar Riot"
            ring.Rotation = mode == "Lunar Riot" and (t * 80) % 360 or 0
            for i, dot in ipairs(trails) do
                dot.Visible = active
                if mode == "Orbit" then
                    dot.Position = at(0.5 + leftRightRoom * 0.84 * math.cos((t - i * 0.11) * 2.4), centerY + roomY * 0.9 * math.sin((t - i * 0.11) * 2.4))
                else dot.Position = at(math.clamp(x - i * 0.025, 0.05, 0.95), math.clamp(y + i * 0.012, 0.22, 0.82)) end
            end
            for i, beam in ipairs(streaks) do
                beam.Visible = streakOn
                beam.Size = UDim2.new(0.24 + 0.16 * math.abs(math.sin(t * 8 + i)), 0, 0, 1)
            end
            local text = mode == "Fake Position" and ("LOCAL GHOST / +" .. string.format("%.3g", status.GhostHeight) .. " STUDS") or captions[mode] or "LIVE / MOVEMENT PREVIEW"
            if foot.Text ~= text then foot.Text = text end
        end)
        return status
    end

    function ui:CreateWindow(title)
        local assets = {}
        pcall(function() assets = loadFrekksecAssets() end)
        self.Assets = assets
        if assets.Frost then
            Sakura:SetFrost(assets.Frost)
            assets:FetchFrost()
        end
        local window = Sakura:CreateWindow({
            Title = title,
            Logo = assets.Logo,
            Size = UDim2.fromOffset(1010, 590),
            ToggleKey = Enum.KeyCode.Insert,
            Footer = "frekksec lua  |  F6 helper  |  X fake position  |  End panic",
        })
        Sakura:SetNotifications({Side = "Left", Anchor = "Top"})
        self.Window, self.ScreenGui = window, Sakura:GetScreenGui()
        private.ScreenGui = self.ScreenGui
        private.Cleanup = function() self:Unload() end
        local mark = {text = "", visible = true}
        function mark:SetFields(values)
            local parts = {}
            for index, value in ipairs(values) do parts[index] = tostring(value) end
            self.text = table.concat(parts, " | ")
            if self.visible then Sakura:SetWatermark(self.text) end
        end
        function mark:SetVisible(value)
            self.visible = value == true
            if self.visible and self.text ~= "" then Sakura:SetWatermark(self.text) else Sakura:SetWatermark(false) end
        end
        self.Mark = mark
        self.Side = buildStatus(window)
        self:UpdateColorsUsingRegistry()
        local facade = {Holder = window.Instance, Background = window.Backdrop}
        function facade:AddTab(name)
            local actual = window:AddTab(name)
            local tab = surface(actual)
            function tab:AddSubTab(subName) return surface(actual:AddSubTab(subName)) end
            function tab:SetBuilder(builder) actual:SetBuilder(builder) end
            function tab:ShowTab() window:SelectTab(actual) end
            return tab
        end
        return facade
    end
    return ui
end

